const bankModules = "[{moduleId:`bank-01-riksbanken-1668`,moduleTitle:`01 · Riksbanken 1668 – från de första sedlarna till världens äldsta centralbank`,moduleTitleEn:`01 · The Riksbank 1668 – from the first banknotes to the world’s oldest central bank`,summary:`Stockholms Banco gav ut Europas första sedlar 1661. Ur den erfarenheten grundades Riksens Ständers Bank 1668, i dag Sveriges riksbank.`,summaryEn:`Stockholms Banco issued Europe’s first banknotes in 1661. From that experience the Estates’ Bank was founded in 1668 – today Sveriges Riksbank.`,durationMinutes:12,topics:[`Riksbanken`,`Stockholms Banco`,`Sedlar`,`Förtroende`,`Quiz`],topicsEn:[`Riksbank`,`Stockholms Banco`,`Banknotes`,`Trust`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur Stockholms Banco gav ut Europas första sedlar,`,`• förklara hur Riksbanken grundades 1668,`,`• nämna Riksbankens inflationsmål i dag.`,`# Sveriges första bank`,`År 1656 fick Johan Palmstruch privilegier för en växelbank och en lånebank. Tillsammans blev de Stockholms Banco, Sveriges första bank. [K2][K7]`,`# Europas första sedlar`,`År 1660 började staten prägla nya mynt med lägre vikt. Många insättare ville då ta ut sina gamla, tyngre mynt, och det blev rusning till banken. [K3]`,`År 1661 började Stockholms Banco ge ut kreditivsedlar. De lämnades ut som lån och kunde användas för att köpa varor. Det var de första sedlarna i Europa. [K3]`,`Med sedlarna kunde banken låna ut så mycket som den var beredd att ge ut i sedlar. [K7]`,`# Från succé till krasch`,`Sedlarna blev populära eftersom de var lättare att hantera än tunga kopparmynt. Banken gav ut allt fler sedlar och de minskade i värde. Allmänheten ville växla in sedlarna mot mynt, banken hade för få mynt i kassan och det slutade med en bankkrasch. [K3]`,`Riksrådet beslöt 1664 att lånen skulle betalas tillbaka och sedlarna drogs in. [K3]`,`# 1668: Riksens Ständers Bank`,`År 1668 beslutade riksdagen att grunda Riksens Ständers Bank ur Stockholms Banco, med adeln, prästerna och borgarna som huvudmän. Ständerna förbjöd sedlar i den nya banken. [K1][K2]`,`Banken fick namnet Sveriges riksbank 1867. År 1904 fick Riksbanken ensamrätt att ge ut sedlar. [K4]`,`Riksbanken beskriver sig själv som världens äldsta centralbank. [K1]`,`# Riksbanken i dag`,`År 1931 fick Riksbanken, som första centralbank i världen, ett prisstabilitetsmål. [K4]`,`I dag är målet att inflationen ska vara 2 procent per år, mätt med KPIF (konsumentprisindex med fast ränta). [K6]`,`# Sammanfattning`,`Stockholms Banco visade både hur praktiska sedlar är och hur viktigt förtroende är. Riksbanken växte fram ur den erfarenheten. [K2][K3]`,`# Källor`,`• [K1] Sveriges riksbank: Historia – https://www.riksbank.se/sv/om-riksbanken/historia/`,`• [K2] Sveriges riksbank: Sveriges riksbank grundas (1668) – https://www.riksbank.se/sv/om-riksbanken/historia/historisk-tidslinje/1600-1699/sveriges-riksbank-grundas/`,`• [K3] Sveriges riksbank: 1661 – Premiär för sedlar i Europa – https://www.riksbank.se/sv/om-riksbanken/historia/historisk-tidslinje/1600-1699/premiar-for-sedlar-i-europa/`,`• [K4] Sveriges riksbank: Historisk tidslinje – https://www.riksbank.se/sv/om-riksbanken/historia/historisk-tidslinje/`,`• [K6] Sveriges riksbank: Inflationsmålet (uppd. 2026-01-20) – https://www.riksbank.se/sv/penningpolitik/inflationsmalet/`,`• [K7] Sveriges riksbank, 350-årsjubileet: Stockholms Banco (PDF) – https://www.riksbank.se/globalassets/media/riksbanken-350-ar/tidslinjen/stockholm-banco/24-45-stockholm-banco.pdf`,`⚠️ Endast utbildning. Förenklad historia. Detta är inte råd.`],quiz:[{id:`bank1-q1`,prompt:`Vad hette Sveriges första bank?`,options:[xs(`a`,`Riksens Ständers Bank`,!1),xs(`b`,`Stockholms Banco`,!0),xs(`c`,`Sveriges riksbank`,!1),xs(`d`,`Skånska privatbanken`,!1)],explanation:`Johan Palmstruch fick privilegier 1656 för det som blev Stockholms Banco. [K2]`},{id:`bank1-q2`,prompt:`Vad var kreditivsedlarna?`,options:[xs(`a`,`Europas första sedlar, utgivna av Stockholms Banco 1661`,!0),xs(`b`,`Riksbankens första mynt`,!1),xs(`c`,`Statsobligationer från 1789`,!1),xs(`d`,`Kvitton från guldsmeder i London`,!1)],explanation:`Kreditivsedlarna lämnades ut som lån och användes som betalning. [K3]`},{id:`bank1-q3`,prompt:`Vilket år beslutade riksdagen att grunda Riksens Ständers Bank?`,options:[xs(`a`,`1656`,!1),xs(`b`,`1694`,!1),xs(`c`,`1668`,!0),xs(`d`,`1867`,!1)],explanation:`Banken grundades 1668 och fick namnet Sveriges riksbank 1867. [K1]`},{id:`bank1-q4`,prompt:`Vilket mål har Riksbanken för inflationen i dag?`,options:[xs(`a`,`0 procent`,!1),xs(`b`,`2 procent per år, mätt med KPIF`,!0),xs(`c`,`5 procent per år`,!1),xs(`d`,`Samma som Federal Reserve`,!1)],explanation:`Målet är 2 procent per år för KPIF. [K6]`}],relatedLinks:[{to:`/tradingskolan?course=historia&lesson=hist-02-guld-korsfarare`,labelSv:`Marknadens historia: Guld & korsfarare`,labelEn:`Market history: Gold & crusaders`,descriptionSv:`Tidig kredit före bankerna`,descriptionEn:`Early credit before the banks`}]},{moduleId:`bank-02-bank-of-england-1694`,moduleTitle:`02 · Bank of England 1694 – banken som lånade ut till staten`,moduleTitleEn:`02 · Bank of England 1694 – the bank that lent to the state`,summary:`Guldsmeder, ett statslån på 1,2 miljoner pund och en bank som med tiden blev Storbritanniens centralbank.`,summaryEn:`Goldsmiths, a £1.2 million loan to the state and a bank that over time became the UK’s central bank.`,durationMinutes:12,topics:[`Bank of England`,`Guldsmeder`,`Statslån`,`Guldmyntfot`,`Quiz`],topicsEn:[`Bank of England`,`Goldsmiths`,`Government loans`,`Gold standard`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara varför Bank of England grundades 1694,`,`• beskriva guldsmedernas roll i tidig engelsk bankverksamhet,`,`• nämna några viktiga steg fram till dagens självständiga centralbank.`,`# Guldsmederna`,`På 1600-talet sköttes tidig bankverksamhet i England av guldsmeder. De förvarade och lånade ut guld och silver, ofta till räntor på 20–30 procent. [K9]`,`Guldsmederna gav ut kvitton på mynt som de förvarade, och kvittona började cirkulera som ett slags pengar. [K12]`,`År 1672 stoppade kung Karl II återbetalningen av sina lån från guldsmederna. Många guldsmedsfirmor gick omkull och förtroendet för branschen sjönk. [K9]`,`# En ny idé: allmänheten lånar ut till staten`,`Kung Vilhelm III behövde pengar till kriget mot Frankrike. Den skotske köpmannen William Paterson föreslog att allmänheten skulle låna staten 1,2 miljoner pund. [K9]`,`Långivarna blev delägare i ett nytt aktiebolag, «The Governor and Company of the Bank of England». Staten betalade 8 procent i ränta. [K9]`,`Beloppet samlades in på 11 dagar av 1 268 personer. [K9]`,`Banken bildades genom ett kungligt privilegiebrev den 27 juli 1694 och öppnade den 1 augusti 1694 med 17 kontorister och två grindvakter. [K8]`,`# Sedlar och guld`,`Bank of Englands första sedlar gick att växla mot guld. [K12]`,`År 1797 beordrade premiärminister William Pitt d.y. banken att sluta lösa in sedlar mot guld. Den så kallade restriktionsperioden varade till 1821. [K8]`,`Bank Charter Act 1844 gav banken nya befogenheter, reglerade sedelutgivningen och stoppade nya banker från att börja ge ut egna sedlar. [K8]`,`# Långivare i sista hand`,`År 1866 ställde diskonthuset Overend Gurney in betalningarna. Debatten efteråt formade Bank of Englands roll som långivare i sista hand (lender of last resort). [K8]`,`# Mot dagens centralbank`,`År 1931 lämnade Storbritannien guldmyntfoten. Sedan dess är Bank of Englands pengar fiatpengar. [K8][K12]`,`År 1946 förstatligades banken. [K8][K10]`,`Sedan maj 1997 sätter Bank of England räntan självständigt för att nå inflationsmålet på 2 procent, som regeringen bestämmer. [K10]`,`# Sammanfattning`,`Bank of England började som en bank som lånade ut till staten och blev med tiden Storbritanniens centralbank. [K8]`,`# Källor`,`• [K8] Bank of England: Our history – https://www.bankofengland.co.uk/about/history`,`• [K9] Bank of England Museum: Why was the Bank of England founded? (2021) – https://www.bankofengland.co.uk/museum/online-collections/blog/why-was-the-bank-of-england-founded`,`• [K10] Bank of England: How is the Bank of England independent of the Government? – https://www.bankofengland.co.uk/explainers/how-is-the-bank-of-england-independent-of-the-government`,`• [K12] McLeay, Radia & Thomas (2014): Money in the modern economy: an introduction, Quarterly Bulletin 2014 Q1 (PDF) – https://www.bankofengland.co.uk/-/media/boe/files/quarterly-bulletin/2014/money-in-the-modern-economy-an-introduction.pdf`,`⚠️ Endast utbildning. Förenklad historia. Detta är inte råd.`],quiz:[{id:`bank2-q1`,prompt:`Varför grundades Bank of England 1694?`,options:[xs(`a`,`För att ge ut mynt till kolonierna`,!1),xs(`b`,`För att låna staten pengar till kriget mot Frankrike`,!0),xs(`c`,`För att ersätta Riksbanken`,!1),xs(`d`,`För att driva börsen i London`,!1)],explanation:`Allmänheten lånade staten 1,2 miljoner pund och blev delägare i banken. [K9]`},{id:`bank2-q2`,prompt:`Hur mycket lånade allmänheten ut till staten när banken bildades?`,options:[xs(`a`,`1,2 miljoner pund`,!0),xs(`b`,`12 000 pund`,!1),xs(`c`,`4 miljoner pund`,!1),xs(`d`,`120 miljoner pund`,!1)],explanation:`Beloppet samlades in på 11 dagar. [K9]`},{id:`bank2-q3`,prompt:`Vad hände med guldsmedernas kvitton?`,options:[xs(`a`,`De brändes varje år`,!1),xs(`b`,`De började cirkulera som ett slags pengar`,!0),xs(`c`,`De blev aktier i Bank of England`,!1),xs(`d`,`De användes bara inom familjen`,!1)],explanation:`Kvittona på förvarade mynt började användas som betalning. [K12]`},{id:`bank2-q4`,prompt:`Sedan när sätter Bank of England räntan självständigt?`,options:[xs(`a`,`1694`,!1),xs(`b`,`1844`,!1),xs(`c`,`1946`,!1),xs(`d`,`1997`,!0)],explanation:`Självständigheten i penningpolitiken gäller sedan maj 1997. [K10]`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-01-riksbanken-1668`,labelSv:`Föregående: Riksbanken 1668`,labelEn:`Previous: The Riksbank 1668`}]},{moduleId:`bank-03-rothschild-1800-talet`,moduleTitle:`03 · Familjen Rothschild och 1800-talets europeiska banker`,moduleTitleEn:`03 · The Rothschild family and 19th-century European banking`,summary:`Mayer Amschel Rothschild och hans fem söner byggde bankhus i fem städer och skötte statslån, guldtransporter och järnvägsfinansiering.`,summaryEn:`Mayer Amschel Rothschild and his five sons built banking houses in five cities and handled government loans, gold shipments and railway finance.`,durationMinutes:14,topics:[`Rothschild`,`Statslån`,`Guld`,`Järnvägar`,`Quiz`],topicsEn:[`Rothschild`,`Government loans`,`Gold`,`Railways`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur familjen Rothschild byggde bankhus i fem europeiska städer,`,`• ge exempel på statslån och uppdrag som familjens banker skötte,`,`• förklara hur familjens verksamhet följde industrialiseringen.`,`# Frankfurt och fem söner`,`Bankhuset grundades av Mayer Amschel Rothschild (1744–1812) från Frankfurt am Main och hans fem söner: Amschel, Salomon, Nathan, Karl och Jakob (James). [K22]`,`Mayer Amschel arbetade vid hovet hos lantgreve Vilhelm IX av Hessen-Kassel och gjorde helst affärer med regerande furstehus. [K22]`,`Sönerna spred verksamheten över Europa. Amschel stannade i Frankfurt, Nathan etablerade sig i London, Jakob i Paris 1811, och Salomon och Karl öppnade kontor i Wien och Neapel på 1820-talet. [K22][K28]`,`# Nathan i London`,`Nathan Mayer Rothschild kom till Storbritannien 1798 och drev först textilhandel i Manchester. År 1809 grundade han N M Rothschild vid New Court i Londons finanskvarter, och 1811 satsade han helt på bankverksamhet. [K23]`,`Nathan byggde upp ett stort nätverk av kurirer, handlare, mäklare och bankirer för sin handel med guld. [K24]`,`# Guld till Wellingtons armé`,`Hertigen av Wellingtons armé behövde guld- och silvermynt för att betala och försörja soldaterna. I januari 1814 anlitade den brittiska regeringens generalkommissarie J.C. Herries Nathan för att i hemlighet skaffa stora mängder guld. [K24]`,`Nathans bröder köpte guld runt om i Europa i små poster, och guldet skeppades till Wellington i södra Frankrike. År 1815 fick Nathan ett liknande uppdrag igen. [K24]`,`Efter kriget fick Londonhuset uppdraget att förmedla Storbritanniens subsidier till de allierade. [K23][K25]`,`# Statslån och en räddning i guld`,`Mellan 1818 och 1835 gav Nathans Londonhus ut 26 brittiska och utländska statslån. [K25]`,`År 1826 tillförde firman snabbt guld till Bank of England. [K23][K25]`,`Efter freden 1815 arbetade familjens banker allt mer med statspapper från bland annat Preussen, England, Frankrike och Neapel, med försäkringsaktier och med aktier i industribolag. [K22]`,`# Järnvägar och industri`,`Familjen följde industrialiseringen med investeringar i järnvägar, kol, järnbruk och metallindustri. [K22]`,`Londonhuset specialiserade sig på utländska lån, guldhandel och finansiering av allmännyttiga bolag, särskilt utländska järnvägar. [K23]`,`# Två stora lån på 1870-talet`,`Åren 1871–1872 ledde Alphonse de Rothschild, Jakobs son, det bankkonsortium som placerade Frankrikes två stora «befrielselån» efter kriget mot Preussen. [K22]`,`År 1875 lånade N M Rothschild & Sons premiärminister Benjamin Disraeli 4 miljoner pund. Pengarna användes till att köpa Egyptens khediv aktier i Suezkanalbolaget åt den brittiska regeringen. Lånet återbetalades inom fem månader. [K26][K22]`,`Underhuset beviljade den 21 februari 1876 anslaget på 4 080 000 pund för Suezaktierna. [K27]`,`# Sammanfattning`,`Familjen Rothschild byggde ett nätverk av bankhus i fem städer och skötte under 1800-talet stora statslån, guldtransporter och järnvägsfinansiering. [K22][K23]`,`Fördjupning: Niall Ferguson, *The House of Rothschild* (två band). [K32][K33]`,`# Källor`,`• [K22] Encyclopaedia Britannica (J. Bouvier): Rothschild family (uppd. 2026-09-26) – https://www.britannica.com/topic/Rothschild-family`,`• [K23] The Rothschild Archive: London banking house – https://www.rothschildarchive.org/business/n_m_rothschild_and_sons_london`,`• [K24] The Rothschild Archive: Rothschild and gold – https://www.rothschildarchive.org/business/n_m_rothschild_and_sons_london/rothschild_and_gold`,`• [K25] The Rothschild Archive: Nathan Mayer Rothschild (1777–1836) – https://family.rothschildarchive.org/people/25-nathan-mayer-rothschild-1777-1836`,`• [K26] The Rothschild Archive: Lionel de Rothschild and the Suez Canal – https://www.rothschildarchive.org/business/n_m_rothschild_and_sons_london/lionel_de_rothschild_and_the_suez_canal`,`• [K27] Hansard, House of Commons 21 februari 1876: Supply – £4,080,000 Suez Canal Shares – https://api.parliament.uk/historic-hansard/commons/1876/feb/21/supply-lb4080000-suez-canal-shares`,`• [K28] The Rothschild Archive: The Naples house, C M de Rothschild e figli – https://www.rothschildarchive.org/business/c_m_de_rothschild_and_figli_naples`,`• [K32] Niall Ferguson: The House of Rothschild, Vol. 1: Money's Prophets 1798–1848 (Viking 1998 / Penguin 1999) – https://www.penguinrandomhouse.com/books/331138/the-house-of-rothschild-by-niall-ferguson/`,`• [K33] Niall Ferguson: The House of Rothschild, Vol. 2: The World's Banker 1849–1999 – https://www.niallferguson.com/the-house-of-rothschild-vol-2`,`⚠️ Endast utbildning. Förenklad historia. Detta är inte råd.`],quiz:[{id:`bank3-q1`,prompt:`I vilken stad började familjen Rothschilds bankhus?`,options:[xs(`a`,`London`,!1),xs(`b`,`Paris`,!1),xs(`c`,`Frankfurt am Main`,!0),xs(`d`,`Wien`,!1)],explanation:`Mayer Amschel Rothschild grundade bankhuset i Frankfurt tillsammans med sina fem söner. [K22]`},{id:`bank3-q2`,prompt:`Vilket uppdrag fick Nathan Rothschild av den brittiska regeringen i januari 1814?`,options:[xs(`a`,`Att bygga en järnväg`,!1),xs(`b`,`Att skaffa guld- och silvermynt till Wellingtons armé`,!0),xs(`c`,`Att grunda Bank of England`,!1),xs(`d`,`Att köpa aktier i Suezkanalen`,!1)],explanation:`Generalkommissarie Herries anlitade Nathan för att skaffa guld till armén. [K24]`},{id:`bank3-q3`,prompt:`Hur många statslån gav Nathans Londonhus ut mellan 1818 och 1835?`,options:[xs(`a`,`2`,!1),xs(`b`,`26`,!0),xs(`c`,`260`,!1),xs(`d`,`6`,!1)],explanation:`Londonhuset gav ut 26 brittiska och utländska statslån. [K25]`},{id:`bank3-q4`,prompt:`Vad användes lånet på 4 miljoner pund till 1875?`,options:[xs(`a`,`Den brittiska regeringens köp av khedivens aktier i Suezkanalbolaget`,!0),xs(`b`,`Frankrikes befrielselån`,!1),xs(`c`,`Bygget av New Court`,!1),xs(`d`,`Kriget mot Napoleon`,!1)],explanation:`Lånet gick till Disraeli för köpet av Suezaktierna och återbetalades inom fem månader. [K26]`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-02-bank-of-england-1694`,labelSv:`Föregående: Bank of England 1694`,labelEn:`Previous: Bank of England 1694`}]},{moduleId:`bank-04-rothschild-efter-1800-talet`,moduleTitle:`04 · Rothschildhusen efter 1800-talet – en bankvärld i förändring`,moduleTitleEn:`04 · The Rothschild houses after the 19th century – a changing banking world`,summary:`Aktiebanker och insättningsbanker växte fram. Rothschildhusen i Neapel, Frankfurt, Wien och Paris avvecklades, såldes eller förstatligades, och 1989 öppnade ett nytt kontor i Frankfurt.`,summaryEn:`Joint-stock and deposit banks grew. The Rothschild houses in Naples, Frankfurt, Vienna and Paris were wound up, sold or nationalised, and in 1989 a new office opened in Frankfurt.`,durationMinutes:10,topics:[`Rothschild`,`Aktiebanker`,`Förstatligande`,`Quiz`],topicsEn:[`Rothschild`,`Joint-stock banks`,`Nationalisation`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur nya typer av banker växte fram efter 1850,`,`• nämna vad som hände med husen i Neapel, Frankfurt, Wien och Paris,`,`• förklara hur bankverksamheten återkom till Frankfurt 1989.`,`# Nya konkurrenter`,`Från 1850-talet växte nya aktiebanker och insättningsbanker fram i England, Frankrike och de tyska staterna. Under 1800-talets sista kvartal hade andra bankgrupper i Europa och USA blivit större och rikare än Rothschildgruppen. [K22]`,`# Neapel 1863`,`Italiens enande 1860 minskade Neapels betydelse. Huset i Neapel, C M de Rothschild e figli, avvecklades 1863 efter 42 år. [K28][K29]`,`# Frankfurt 1901`,`När den siste delägaren, Wilhelm Carl von Rothschild, dog 1901 hade Frankfurt fått mindre betydelse som finanscentrum. Familjen beslöt att likvidera M A Rothschild & Söhne. [K29]`,`# Wien 1938`,`Vid Tysklands annektering av Österrike 1938 tvingades familjen lämna Wien. År 1939 ställdes S M von Rothschild under det tyska bankhuset Merck, Finck & Co och såldes sedan till dem. [K30]`,`Efter kriget fick familjen viss ersättning och valde att avsluta bankverksamheten i Wien för gott. [K30]`,`# Paris 1981–1982`,`År 1967 blev de Rothschild Frères aktiebolaget Banque Rothschild. [K31]`,`London och Paris var då de sista kvarvarande husen och gjorde allt fler affärer tillsammans. [K31]`,`Åren 1981–1982 var Banque Rothschild en av 39 banker som den franska regeringen förstatligade. Banken fick namnet Compagnie Européenne de Banque. [K31]`,`# Tillbaka i Frankfurt 1989`,`År 1989 öppnade London- och Parishusen dotterbolaget Rothschild GmbH i Frankfurt, staden där Mayer Amschel Rothschild en gång startade. [K29]`,`# Sammanfattning`,`Under 1900-talet förändrades bankvärlden: aktiebanker, insättningsbanker och statliga beslut formade marknaden, och Rothschildhusen i Neapel, Frankfurt, Wien och Paris avvecklades, såldes eller förstatligades. [K22][K28][K29][K30][K31]`,`# Källor`,`• [K22] Encyclopaedia Britannica (J. Bouvier): Rothschild family (uppd. 2026-09-26) – https://www.britannica.com/topic/Rothschild-family`,`• [K28] The Rothschild Archive: The Naples house, C M de Rothschild e figli – https://www.rothschildarchive.org/business/c_m_de_rothschild_and_figli_naples`,`• [K29] The Rothschild Archive: Rothschild Timeline – https://www.rothschildarchive.org/exhibitions/timeline`,`• [K30] The Rothschild Archive: The Vienna house, S M von Rothschild – https://www.rothschildarchive.org/business/s_m_von_rothschild_vienna`,`• [K31] The Rothschild Archive: Paris banking house, de Rothschild Frères – https://www.rothschildarchive.org/business/de_rothschild_freres_paris`,`⚠️ Endast utbildning. Förenklad historia. Detta är inte råd.`],quiz:[{id:`bank4-q1`,prompt:`Vilket av Rothschildhusen avvecklades först?`,options:[xs(`a`,`London`,!1),xs(`b`,`Neapel, 1863`,!0),xs(`c`,`Paris`,!1),xs(`d`,`Wien`,!1)],explanation:`Efter Italiens enande avvecklades huset i Neapel 1863. [K28]`},{id:`bank4-q2`,prompt:`Varför likviderades Frankfurthuset 1901?`,options:[xs(`a`,`Den siste delägaren dog och Frankfurt hade fått mindre betydelse som finanscentrum`,!0),xs(`b`,`Huset flyttade till New York`,!1),xs(`c`,`Det slogs ihop med Bank of England`,!1),xs(`d`,`Det köptes av Riksbanken`,!1)],explanation:`Wilhelm Carl von Rothschild dog 1901 och familjen beslöt att likvidera banken. [K29]`},{id:`bank4-q3`,prompt:`Vad hände med Banque Rothschild i Paris 1981–1982?`,options:[xs(`a`,`Banken flyttade till London`,!1),xs(`b`,`Banken blev centralbank`,!1),xs(`c`,`Banken förstatligades av den franska regeringen`,!0),xs(`d`,`Banken börsnoterades i USA`,!1)],explanation:`Banque Rothschild var en av 39 banker som förstatligades. [K31]`},{id:`bank4-q4`,prompt:`Vilka typer av banker växte fram från 1850-talet?`,options:[xs(`a`,`Tempelbanker`,!1),xs(`b`,`Aktiebanker och insättningsbanker`,!0),xs(`c`,`Kryptobanker`,!1),xs(`d`,`Centralbanker i varje stad`,!1)],explanation:`Britannica beskriver hur nya aktiebanker och insättningsbanker växte i England, Frankrike och de tyska staterna. [K22]`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-03-rothschild-1800-talet`,labelSv:`Föregående: Rothschild på 1800-talet`,labelEn:`Previous: Rothschild in the 19th century`}]},{moduleId:`bank-05-delreservsystemet`,moduleTitle:`05 · Delreservsystemet – hur bankpengar skapas`,moduleTitleEn:`05 · Fractional reserve banking – how bank money is created`,summary:`Så skapar banker pengar när de lånar ut, vad reservkrav och kapitalkrav är, och hur insättningsgarantin skyddar sparare.`,summaryEn:`How banks create money when they lend, what reserve and capital requirements are, and how deposit insurance protects savers.`,durationMinutes:14,topics:[`Delreserv`,`Bankpengar`,`Kapitalkrav`,`Likviditet`,`Quiz`],topicsEn:[`Fractional reserve`,`Bank money`,`Capital requirements`,`Liquidity`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad ett reservkrav och ett delreservsystem är,`,`• beskriva hur banker skapar pengar när de lånar ut,`,`• nämna vad som begränsar bankernas utlåning i dag.`,`# Grundidén`,`I ett delreservsystem (fractional reserve banking) håller bankerna reserver som motsvarar en andel av insättningarna. Ett reservkrav innebär att banker måste hålla reserver som motsvarar en fast andel av sina insättningar. [K11]`,`# Rötterna`,`Guldsmedernas kvitton på förvarade mynt började cirkulera som pengar. [K12]`,`Stockholms Banco kunde med sina kreditivsedlar låna ut så mycket som banken var beredd att ge ut i sedlar. [K7]`,`# Så skapas pengar i dag`,`I dag består de flesta pengar av bankinsättningar. I Storbritannien utgjorde bankinsättningar 97 procent av de breda pengarna när Bank of England skrev om saken 2014. [K11]`,`I Sverige utgör kontanter ungefär 1,5 procent av pengarna. Resten finns på bankkonton. [K5]`,`När en bank lämnar ett lån skapar den samtidigt en lika stor insättning på låntagarens konto. Det är nya pengar. [K11][K5]`,`När lånet betalas tillbaka minskar mängden bankpengar. [K5]`,`# Två sorters pengar`,`• **Centralbankspengar:** sedlar, mynt och bankernas pengar på konton i Riksbankens betalningssystem RIX. [K5]`,`• **Bankpengar:** pengar på konton i vanliga banker. De är en fordran på banken. [K5]`,`# Vad begränsar utlåningen?`,`Enligt Riksbanken begränsas bankernas utlåning av lagar och regler, bland annat krav på likviditet och kapital, och av hur mycket lån allmänheten efterfrågar. Riksbanken påverkar efterfrågan på lån genom styrräntan. [K5]`,`Enligt Bank of England beror mängden pengar ytterst på centralbankens penningpolitik: normalt räntan, och ibland köp av tillgångar (kvantitativa lättnader). [K11]`,`# Reservkrav i dag`,`• Enligt Bank of England (2014) spelar reservkrav en liten roll i penningpolitiken i de flesta avancerade ekonomier. [K11]`,`• I USA sänkte Federal Reserve reservkraven till 0 procent den 26 mars 2020. Före dess gällde 3 procent och 10 procent på transaktionskonton, beroende på belopp. [K13]`,`• I euroområdet kräver ECB att kreditinstitut håller minimireserver på konton hos sin nationella centralbank. [K14]`,`• I Sverige sattes Riksbankens kassakrav, alltså reservkravet i penningpolitiken, till 0 procent 1994. Där låg det när Riksbanken beskrev saken 2020. [K38]`,`• Sedan den 1 januari 2025 kan Riksbanken kräva räntefri inlåning av kreditinstituten. Från den 11 juni 2026 håller banker och andra kreditinstitut med verksamhet i Sverige 0,2944 procent av sin inlåningsbas som räntefri inlåning i Riksbanken, sammanlagt knappt 35 miljarder kronor. Syftet är att stärka Riksbankens förmåga att finansiera sig själv. Riksbanken prövar kravet varje år. [K36][K37]`,`# Kapitalregler`,`Efter bankkollapser 1974 bildade centralbankscheferna i G10 Baselkommittén för banktillsyn. Baselkommittén gav ut Basel Capital Accord 1988, och ramverket har sedan utvecklats i Basel II (2004) och Basel III (2017). [K15]`,`# Skydd för insättare`,`Staten skyddar insättningar på bankkonton upp till ett visst belopp genom insättningsgarantin. [K5]`,`Insättningsgarantin ersätter kapital och ränta upp till 1 150 000 kronor per person och institut. Beloppet gäller sedan den 1 januari 2026. [K39][K40]`,`För insättningar som hör ihop med vissa livshändelser, till exempel försäljning av en bostad, kan ersättningen bli upp till 5 miljoner kronor. [K40]`,`# Sammanfattning`,`Banker skapar pengar när de lånar ut. Kapitalkrav, likviditetskrav, efterfrågan på lån och centralbankens ränta sätter ramarna. [K5][K11]`,`# Källor`,`• [K5] Sveriges riksbank: Vad är pengar? (uppd. 2026-06-29) – https://www.riksbank.se/sv/betalningar--kontanter/vad-ar-pengar/`,`• [K7] Sveriges riksbank, 350-årsjubileet: Stockholms Banco (PDF) – https://www.riksbank.se/globalassets/media/riksbanken-350-ar/tidslinjen/stockholm-banco/24-45-stockholm-banco.pdf`,`• [K11] McLeay, Radia & Thomas (2014): Money creation in the modern economy, Bank of England Quarterly Bulletin 2014 Q1 – https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-creation-in-the-modern-economy`,`• [K12] McLeay, Radia & Thomas (2014): Money in the modern economy: an introduction, Quarterly Bulletin 2014 Q1 (PDF) – https://www.bankofengland.co.uk/-/media/boe/files/quarterly-bulletin/2014/money-in-the-modern-economy-an-introduction.pdf`,`• [K13] Federal Reserve Board: Reserve Requirements – https://www.federalreserve.gov/monetarypolicy/reservereq.htm`,`• [K14] Europeiska centralbanken: Minimum reserves – https://www.ecb.europa.eu/mopo/implement/mr/html/index.en.html`,`• [K15] BIS: The story of the BIS – https://www.bis.org/about/history.htm`,`• [K36] Sveriges riksbank: Riksbanken har beslutat om räntefri inlåning på knappt 35 miljarder kronor (nyhet 2026-05-08) – https://www.riksbank.se/sv/press-och-publicerat/nyheter-och-pressmeddelanden/nyheter/2026/riksbanken-har-beslutat-om-rantefri-inlaning-pa-knappt-35-miljarder-kronor/`,`• [K37] Sveriges riksbank: Räntefri inlåning (inlåningskrav) (uppd. 2026-09-25) – https://www.riksbank.se/sv/marknader/rantefri-inlaning/`,`• [K38] Sveriges riksbank, Ekonomiska kommentarer nr 4 2020 (Armelius, Claussen & Vestin): Pengar och penningpolitik i kristider (PDF) – https://www.riksbank.se/globalassets/media/rapporter/ekonomiska-kommentarer/svenska/2020/pengar-och-penningpolitik-i-kristider.pdf`,`• [K39] Riksgälden: Insättningsgarantin och investerarskyddet – https://www.riksgalden.se/sv/insattningsgarantin/`,`• [K40] Riksgälden: Insättningsgarantins maxbelopp ändras till 1 150 000 kronor (pressmeddelande 2025-10-30) – https://www.riksgalden.se/press-och-publicerat/pressmeddelanden-och-nyheter/pressmeddelanden/2025/insattningsgarantins-maxbelopp-andras-till-1-150-000-kronor/`,`⚠️ Endast utbildning. Förenklad beskrivning. Detta är inte råd.`],quiz:[{id:`bank5-q1`,prompt:`Vad händer enligt Bank of England när en bank lämnar ett lån?`,options:[xs(`a`,`Banken hämtar pengarna från Riksbanken`,!1),xs(`b`,`Banken skapar samtidigt en lika stor insättning på låntagarens konto`,!0),xs(`c`,`Banken trycker nya sedlar`,!1),xs(`d`,`Banken säljer guld`,!1)],explanation:`Lånet skapar en motsvarande insättning, alltså nya pengar. [K11]`},{id:`bank5-q2`,prompt:`Hur stor del av pengarna i Sverige är kontanter enligt Riksbanken?`,options:[xs(`a`,`Ungefär hälften`,!1),xs(`b`,`Ungefär 25 procent`,!1),xs(`c`,`Ungefär 1,5 procent`,!0),xs(`d`,`Ungefär 97 procent`,!1)],explanation:`Den allra största delen av pengarna finns på bankkonton. [K5]`},{id:`bank5-q3`,prompt:`Vad begränsar bankernas utlåning enligt Riksbanken?`,options:[xs(`a`,`Krav på kapital och likviditet, efterfrågan på lån och styrräntans påverkan`,!0),xs(`b`,`Bara mängden guld i valven`,!1),xs(`c`,`Antalet bankkontor`,!1),xs(`d`,`Vädret`,!1)],explanation:`Regler, efterfrågan och styrräntan sätter ramarna. [K5]`},{id:`bank5-q4`,prompt:`Vilket reservkrav har Federal Reserve haft sedan den 26 mars 2020?`,options:[xs(`a`,`10 procent`,!1),xs(`b`,`3 procent`,!1),xs(`c`,`20 procent`,!1),xs(`d`,`0 procent`,!0)],explanation:`Fed sänkte reservkraven till noll procent för alla inlåningsinstitut. [K13]`},{id:`bank5-q5`,prompt:`Vad är bankpengar?`,options:[xs(`a`,`Sedlar från Riksbanken`,!1),xs(`b`,`En fordran på den bank där pengarna finns`,!0),xs(`c`,`Guldmynt`,!1),xs(`d`,`Aktier i banken`,!1)],explanation:`Pengar på ett bankkonto är en fordran på banken. [K5]`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-04-rothschild-efter-1800-talet`,labelSv:`Föregående: Rothschildhusen efter 1800-talet`,labelEn:`Previous: The Rothschild houses after 1900`}]},{moduleId:`bank-06-federal-reserve-1913`,moduleTitle:`06 · Federal Reserve 1913 – USA:s centralbank`,moduleTitleEn:`06 · Federal Reserve 1913 – the central bank of the United States`,summary:`Krisen 1907, Aldrich–Vreeland Act och Federal Reserve Act 1913 – och hur Federal Reserve är uppbyggt i dag.`,summaryEn:`The Panic of 1907, the Aldrich–Vreeland Act and the Federal Reserve Act of 1913 – and how the Federal Reserve is organised today.`,durationMinutes:12,topics:[`Federal Reserve`,`Panik 1907`,`Regionala banker`,`FOMC`,`Quiz`],topicsEn:[`Federal Reserve`,`Panic of 1907`,`Regional banks`,`FOMC`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva vilken kris som ledde fram till Federal Reserve,`,`• förklara hur systemet med regionala banker och en central styrelse växte fram,`,`• nämna Federal Reserves mål och uppbyggnad i dag.`,`# Krisen 1907`,`År 1907 sköttes nödlån av privata banker och clearinghus. [K35]`,`Den privata sammanslutningen New York Clearing House gav sina medlemsbanker lån i form av clearinghuscertifikat. Certifikaten var föregångare till Federal Reserves diskontlån. [K35]`,`Finansmannen J.P. Morgan organiserade privata investeringar och krediter för att stabilisera banksystemet. Han samlade in kontanter från stora finans- och industriföretag till mäklarna på börsen i New York, som därmed kunde hålla öppet. [K16][K35]`,`Kongressen ville därefter ha en lösning som byggde på institutioner i stället för på enskilda förmögna personer. [K16]`,`# Utredningen`,`Den 30 maj 1908 antog kongressen Aldrich–Vreeland Act. Lagen gav möjlighet till nödvaluta och skapade National Monetary Commission med 18 ledamöter, ledd av senator Nelson Aldrich. [K16]`,`Kommissionen reste till Europas huvudstäder och höll utfrågningar i USA. I januari 1911 presenterade Aldrich en plan för en National Reserve Association. [K16]`,`# Lagen tar form`,`Efter valet 1912 kontrollerade demokraterna både Vita huset och kongressen. [K16]`,`Kongressledamoten Carter Glass ledde arbetet i representanthuset, med hjälp av professor Henry Parker Willis. Glass förslag byggde på regionala banker. [K16]`,`President Woodrow Wilson ville ha en central tillsynsmyndighet, och en Federal Reserve Board lades till. [K16]`,`Senator Robert L. Owen föreslog högst tolv Reserve Banks. Den slutliga lagen angav mellan åtta och tolv Reserve Banks och tioåriga, förskjutna mandat för styrelsens ledamöter. [K16]`,`President Wilson undertecknade Federal Reserve Act den 23 december 1913. [K16]`,`# Federal Reserve i dag`,`• **Board of Governors** i Washington D.C.: 7 ledamöter med förskjutna mandat på 14 år, nominerade av presidenten och godkända av senaten. [K17]`,`• **12 Federal Reserve Banks** med 24 filialer runt om i landet. [K17]`,`• **FOMC** (Federal Open Market Committee): 12 röstande ledamöter som beslutar om penningpolitiken vid minst åtta möten per år. [K17]`,`• **Mål från kongressen:** maximal sysselsättning och prisstabilitet. [K17]`,`# Sammanfattning`,`Krisen 1907 ledde till fem års utredning och debatt. Resultatet blev 1913 ett system med regionala banker och en central styrelse. [K16]`,`# Källor`,`• [K16] Federal Reserve History: Federal Reserve Act Signed into Law – https://www.federalreservehistory.org/essays/federal-reserve-act-signed`,`• [K17] Federal Reserve Board: The Fed Explained – Who We Are – https://www.federalreserve.gov/aboutthefed/structure-federal-reserve-system.htm`,`• [K35] Federal Reserve History (Moen & Tallman): The Panic of 1907 – https://www.federalreservehistory.org/essays/panic-of-1907`,`⚠️ Endast utbildning. Förenklad historia. Detta är inte råd.`],quiz:[{id:`bank6-q1`,prompt:`Vilken kris ledde fram till arbetet med en amerikansk centralbank?`,options:[xs(`a`,`Finanskrisen 1907`,!0),xs(`b`,`Börskraschen 1929`,!1),xs(`c`,`Krisen 2008`,!1),xs(`d`,`Söderhavsbubblan 1720`,!1)],explanation:`Efter 1907 antogs Aldrich–Vreeland Act och en kommission tillsattes. [K16]`},{id:`bank6-q2`,prompt:`När undertecknades Federal Reserve Act?`,options:[xs(`a`,`4 juli 1900`,!1),xs(`b`,`23 december 1913`,!0),xs(`c`,`15 augusti 1971`,!1),xs(`d`,`27 juli 1694`,!1)],explanation:`President Wilson undertecknade lagen den 23 december 1913. [K16]`},{id:`bank6-q3`,prompt:`Hur många regionala Federal Reserve Banks finns i dag?`,options:[xs(`a`,`5`,!1),xs(`b`,`7`,!1),xs(`c`,`12`,!0),xs(`d`,`50`,!1)],explanation:`Systemet har 12 Reserve Banks med 24 filialer. [K17]`},{id:`bank6-q4`,prompt:`Vilka mål har kongressen gett Federal Reserve?`,options:[xs(`a`,`Högsta möjliga börskurser`,!1),xs(`b`,`Maximal sysselsättning och prisstabilitet`,!0),xs(`c`,`Fast guldpris`,!1),xs(`d`,`Fast växelkurs mot pundet`,!1)],explanation:`FOMC arbetar mot maximal sysselsättning och prisstabilitet. [K17]`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-05-delreservsystemet`,labelSv:`Föregående: Delreservsystemet`,labelEn:`Previous: Fractional reserve banking`}]},{moduleId:`bank-07-bretton-woods-imf`,moduleTitle:`07 · Bretton Woods 1944 och IMF`,moduleTitleEn:`07 · Bretton Woods 1944 and the IMF`,summary:`44 länder möttes i Bretton Woods 1944. Resultatet blev IMF, det som i dag är Världsbanksgruppen och ett växelkurssystem knutet till dollarn och guldet.`,summaryEn:`44 countries met at Bretton Woods in 1944. The result was the IMF, today’s World Bank Group and an exchange-rate system tied to the dollar and gold.`,durationMinutes:13,topics:[`Bretton Woods`,`IMF`,`Världsbanken`,`Guld`,`Dollar`,`Quiz`],topicsEn:[`Bretton Woods`,`IMF`,`World Bank`,`Gold`,`Dollar`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva vad som beslutades i Bretton Woods 1944,`,`• förklara hur växelkurssystemet med dollar och guld fungerade,`,`• nämna IMF:s uppgifter och hur Sverige blev medlem.`,`# Konferensen`,`I juli 1944 samlades delegater från 44 länder på Mount Washington Hotel i Bretton Woods, New Hampshire, för att skapa ett nytt internationellt valutasystem. [K18]`,`Målen var stabila växelkurser, att förhindra konkurrerande devalveringar och att främja ekonomisk tillväxt. [K18]`,`Huvudarkitekterna var John Maynard Keynes, rådgivare till det brittiska finansdepartementet, och Harry Dexter White, chefsekonom för internationella frågor i det amerikanska finansdepartementet. Den antagna planen liknade Whites förslag, med vissa eftergifter till Keynes. [K18]`,`# Två nya institutioner`,`De 730 delegaterna beslutade att bilda två institutioner:`,`• **Internationella valutafonden (IMF)**, som skulle övervaka växelkurserna och låna ut reservvalutor till länder med underskott i betalningsbalansen. [K18]`,`• **Internationella banken för återuppbyggnad och utveckling**, i dag Världsbanksgruppen, som skulle stödja återuppbyggnaden efter kriget och utvecklingen i mindre utvecklade länder. [K18]`,`IMF:s stadga trädde i kraft den 27 december 1945. [K20]`,`# Dollar och guld`,`Länderna höll sina valutor fasta, men justerbara inom 1 procent, mot dollarn. Dollarn var fast mot guld till 35 dollar per uns. [K18]`,`År 1958 blev systemet fullt fungerande, när valutorna blev konvertibla. [K18][K19]`,`# Slutet på systemet`,`Med tiden fanns fler dollar utomlands än USA hade guld. [K19]`,`Den 15 augusti 1971 stängde president Richard Nixon «guldfönstret». Därmed upphörde möjligheten för utländska regeringar att växla dollar mot guld. [K19]`,`Riksbanken beskriver 1973 som året då Bretton Woods-samarbetet upphörde. Samma år gick Sverige med i EG:s valutasamarbete, valutaormen. [K4]`,`# Sverige och IMF`,`Sverige blev medlem i IMF den 31 augusti 1951. [K20][K4]`,`I dag har IMF 191 medlemsländer. [K20][K21]`,`# BIS – centralbankernas bank`,`Banken för internationell betalningsutjämning (BIS) grundades 1930 och är den äldsta internationella finansinstitutionen. [K15]`,`Konferensen i Bretton Woods antog en resolution om att avveckla BIS. Europeiska centralbanker verkade för att behålla banken, och 1948 lades resolutionen åt sidan. [K15]`,`# Sammanfattning`,`Bretton Woods gav världen IMF, Världsbanken och ett system med fasta men justerbara växelkurser knutna till dollarn och guldet. Systemet fungerade fullt ut från 1958 till början av 1970-talet. [K18][K19]`,`# Källor`,`• [K4] Sveriges riksbank: Historisk tidslinje – https://www.riksbank.se/sv/om-riksbanken/historia/historisk-tidslinje/`,`• [K15] BIS: The story of the BIS – https://www.bis.org/about/history.htm`,`• [K18] Federal Reserve History: Creation of the Bretton Woods System – https://www.federalreservehistory.org/essays/bretton-woods-created`,`• [K19] Federal Reserve History: Nixon Ends Convertibility of U.S. Dollars to Gold – https://www.federalreservehistory.org/essays/gold-convertibility-ends`,`• [K20] IMF: List of Members' Date of Entry – https://www.imf.org/external/np/sec/memdir/memdate.htm`,`• [K21] IMF Annual Report 2026: About the IMF – https://www.imf.org/annual-report/2026/what-we-do/about-the-imf/`,`⚠️ Endast utbildning. Förenklad historia. Detta är inte råd.`],quiz:[{id:`bank7-q1`,prompt:`Hur många länder deltog i Bretton Woods-konferensen 1944?`,options:[xs(`a`,`12`,!1),xs(`b`,`44`,!0),xs(`c`,`191`,!1),xs(`d`,`730`,!1)],explanation:`Delegater från 44 länder deltog. 730 var antalet delegater. [K18]`},{id:`bank7-q2`,prompt:`Vilka två institutioner beslutades i Bretton Woods?`,options:[xs(`a`,`Federal Reserve och Bank of England`,!1),xs(`b`,`BIS och ECB`,!1),xs(`c`,`IMF och det som i dag är Världsbanksgruppen`,!0),xs(`d`,`Riksbanken och Riksgälden`,!1)],explanation:`IMF och Internationella banken för återuppbyggnad och utveckling. [K18]`},{id:`bank7-q3`,prompt:`Till vilket pris var dollarn knuten till guld?`,options:[xs(`a`,`20 dollar per uns`,!1),xs(`b`,`35 dollar per uns`,!0),xs(`c`,`100 dollar per uns`,!1),xs(`d`,`1 dollar per gram`,!1)],explanation:`Dollarn var fast mot guld till 35 dollar per uns. [K18]`},{id:`bank7-q4`,prompt:`När stängde president Nixon guldfönstret?`,options:[xs(`a`,`Den 15 augusti 1971`,!0),xs(`b`,`1944`,!1),xs(`c`,`1958`,!1),xs(`d`,`1992`,!1)],explanation:`Beslutet i augusti 1971 inledde slutet på Bretton Woods-systemet. [K19]`},{id:`bank7-q5`,prompt:`När blev Sverige medlem i IMF?`,options:[xs(`a`,`1945`,!1),xs(`b`,`1951`,!0),xs(`c`,`1973`,!1),xs(`d`,`1995`,!1)],explanation:`Sveriges medlemskap gäller från den 31 augusti 1951. [K20]`}],relatedLinks:[{to:`/tradingskolan?course=bankernas-historia&lesson=bank-06-federal-reserve-1913`,labelSv:`Föregående: Federal Reserve 1913`,labelEn:`Previous: Federal Reserve 1913`}]},{moduleId:`bank-08-sa-hanger-det-ihop`,moduleTitle:`08 · Så hänger det ihop i dag`,moduleTitleEn:`08 · How it all connects today`,summary:`Tidslinje, dagens centralbanker, BIS, Baselkommittén och IMF – och Bankkartan med en jämförelse av dagens banker.`,summaryEn:`Timeline, today’s central banks, the BIS, the Basel Committee and the IMF – plus the Bank map comparing today’s banks.`,durationMinutes:12,topics:[`Centralbanker`,`Inflationsmål`,`BIS`,`IMF`,`Bankkartan`,`Quiz`],topicsEn:[`Central banks`,`Inflation targets`,`BIS`,`IMF`,`Bank map`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur centralbankerna arbetar i dag,`,`• förklara hur centralbanker, affärsbanker, BIS och IMF hänger ihop,`,`• hitta en uppdaterad jämförelse av dagens banker i Bankkartan.`,`# Tidslinje`,`• 1661 – Stockholms Banco ger ut Europas första sedlar [K3]`,`• 1668 – Riksens Ständers Bank, i dag Riksbanken, grundas [K1]`,`• 1694 – Bank of England grundas [K8]`,`• 1814–1815 – Nathan Rothschild skaffar guld till Wellingtons armé [K24]`,`• 1844 – Bank Charter Act i Storbritannien [K8]`,`• 1875 – Rothschildlånet för Suezaktierna [K26]`,`• 1913 – Federal Reserve Act [K16]`,`• 1930 – BIS grundas [K15]`,`• 1944 – Bretton Woods-konferensen [K18]`,`• 1971 – Guldfönstret stängs [K19]`,`• 1974 – Baselkommittén bildas [K15]`,`• 1997 – Bank of England får självständighet i penningpolitiken [K10]`,`• 2020 – Federal Reserve sänker reservkraven till 0 procent [K13]`,`# Centralbankerna i dag`,`• **Riksbanken** har inflationsmålet 2 procent per år mätt med KPIF. En ny riksbankslag gäller sedan den 1 januari 2023. [K6][K4]`,`• **Bank of England** sätter räntan självständigt för att nå inflationsmålet på 2 procent, som regeringen bestämmer. [K10]`,`• **Federal Reserve** arbetar mot maximal sysselsättning och prisstabilitet. [K17]`,`# Affärsbankerna`,`Affärsbankerna skapar största delen av pengarna när de lånar ut. Kapitalkrav, likviditetskrav, efterfrågan på lån och centralbankens ränta sätter ramarna. [K5][K11]`,`# Samarbetet mellan länder`,`• **BIS** är en bank för centralbanker. Den ägs av 63 centralbanker från länder som tillsammans står för omkring 95 procent av världens BNP. [K15]`,`• **Baselkommittén** tar fram gemensamma kapitalregler för internationellt aktiva banker, i dag Basel III. [K15]`,`• **IMF** har 191 medlemmar. IMF följer medlemsländernas ekonomi genom återkommande granskningar, lånar ut till länder med betalningsbalansproblem och ger teknisk rådgivning till myndigheter. Enligt årsrapporten 2026 lånade IMF ut totalt 40 miljarder dollar till 18 länder. [K21]`,`# Den röda tråden`,`Riksbanken och Bank of England började som banker med nära band till staten. I dag har de tydliga uppdrag, egna mål och självständighet i penningpolitiken. [K1][K8][K6][K10]`,`Rothschildhusen visar hur privata bankhus skötte stora statslån på 1800-talet. Från 1850-talet växte aktiebanker och insättningsbanker fram som nya aktörer. [K22][K25]`,`Bretton Woods lade grunden för det internationella samarbete som IMF, Världsbanken och BIS står för i dag. [K15][K18]`,`# Så ser det ut i dag – Bankkartan`,`Vill du se hur dagens banker står sig på avgifter, uttag och regler? Bankkartan under Kapital & Strategi samlar en jämförelse med datum för senaste uppdatering.`,`Bankkartan öppnar du under «Video & verktyg» längst ned i lektionen: https://www.kapitalstrategi.com/kapital-och-strategi?tab=bankkarta [K34]`,`Bankkartan är en pedagogisk jämförelse. Kontrollera alltid villkor hos banken själv.`,`# Källor`,`• [K1] Sveriges riksbank: Historia – https://www.riksbank.se/sv/om-riksbanken/historia/`,`• [K3] Sveriges riksbank: 1661 – Premiär för sedlar i Europa – https://www.riksbank.se/sv/om-riksbanken/historia/historisk-tidslinje/1600-1699/premiar-for-sedlar-i-europa/`,`• [K4] Sveriges riksbank: Historisk tidslinje – https://www.riksbank.se/sv/om-riksbanken/historia/historisk-tidslinje/`,`• [K5] Sveriges riksbank: Vad är pengar? (uppd. 2026-06-29) – https://www.riksbank.se/sv/betalningar--kontanter/vad-ar-pengar/`,`• [K6] Sveriges riksbank: Inflationsmålet (uppd. 2026-01-20) – https://www.riksbank.se/sv/penningpolitik/inflationsmalet/`,`• [K8] Bank of England: Our history – https://www.bankofengland.co.uk/about/history`,`• [K10] Bank of England: How is the Bank of England independent of the Government? – https://www.bankofengland.co.uk/explainers/how-is-the-bank-of-england-independent-of-the-government`,`• [K11] McLeay, Radia & Thomas (2014): Money creation in the modern economy, Bank of England Quarterly Bulletin 2014 Q1 – https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-creation-in-the-modern-economy`,`• [K13] Federal Reserve Board: Reserve Requirements – https://www.federalreserve.gov/monetarypolicy/reservereq.htm`,`• [K15] BIS: The story of the BIS – https://www.bis.org/about/history.htm`,`• [K16] Federal Reserve History: Federal Reserve Act Signed into Law – https://www.federalreservehistory.org/essays/federal-reserve-act-signed`,`• [K17] Federal Reserve Board: The Fed Explained – Who We Are – https://www.federalreserve.gov/aboutthefed/structure-federal-reserve-system.htm`,`• [K18] Federal Reserve History: Creation of the Bretton Woods System – https://www.federalreservehistory.org/essays/bretton-woods-created`,`• [K19] Federal Reserve History: Nixon Ends Convertibility of U.S. Dollars to Gold – https://www.federalreservehistory.org/essays/gold-convertibility-ends`,`• [K20] IMF: List of Members' Date of Entry – https://www.imf.org/external/np/sec/memdir/memdate.htm`,`• [K21] IMF Annual Report 2026: About the IMF – https://www.imf.org/annual-report/2026/what-we-do/about-the-imf/`,`• [K22] Encyclopaedia Britannica (J. Bouvier): Rothschild family (uppd. 2026-09-26) – https://www.britannica.com/topic/Rothschild-family`,`• [K24] The Rothschild Archive: Rothschild and gold – https://www.rothschildarchive.org/business/n_m_rothschild_and_sons_london/rothschild_and_gold`,`• [K25] The Rothschild Archive: Nathan Mayer Rothschild (1777–1836) – https://family.rothschildarchive.org/people/25-nathan-mayer-rothschild-1777-1836`,`• [K26] The Rothschild Archive: Lionel de Rothschild and the Suez Canal – https://www.rothschildarchive.org/business/n_m_rothschild_and_sons_london/lionel_de_rothschild_and_the_suez_canal`,`• [K34] Kapital och Strategi: Bankkartan – https://www.kapitalstrategi.com/kapital-och-strategi?tab=bankkarta`,`⚠️ Endast utbildning. Detta är inte råd och inte en rekommendation om någon bank eller produkt.`],quiz:[{id:`bank8-q1`,prompt:`Vem bestämmer Bank of Englands inflationsmål?`,options:[xs(`a`,`Den brittiska regeringen`,!0),xs(`b`,`IMF`,!1),xs(`c`,`Federal Reserve`,!1),xs(`d`,`Bankernas styrelser`,!1)],explanation:`Regeringen sätter målet på 2 procent. Bank of England sätter räntan för att nå det. [K10]`},{id:`bank8-q2`,prompt:`Vad är BIS?`,options:[xs(`a`,`En vanlig sparbank`,!1),xs(`b`,`En bank för centralbanker, ägd av 63 centralbanker`,!0),xs(`c`,`En del av Riksbanken`,!1),xs(`d`,`En börs i Basel`,!1)],explanation:`BIS tjänar centralbanker och främjar samarbete mellan dem. [K15]`},{id:`bank8-q3`,prompt:`Hur många medlemsländer har IMF i dag?`,options:[xs(`a`,`44`,!1),xs(`b`,`63`,!1),xs(`c`,`191`,!0),xs(`d`,`29`,!1)],explanation:`IMF har 191 medlemmar. [K20]`},{id:`bank8-q4`,prompt:`Vilka skapar största delen av pengarna i dag?`,options:[xs(`a`,`Affärsbankerna, när de lånar ut`,!0),xs(`b`,`IMF`,!1),xs(`c`,`Guldgruvor`,!1),xs(`d`,`BIS`,!1)],explanation:`Bankinsättningar är den största delen av pengarna och skapas främst genom utlåning. [K11][K5]`}],relatedLinks:[{to:`/kapital-och-strategi?tab=bankkarta`,labelSv:`Bankkartan`,labelEn:`Bank map`,descriptionSv:`Dagens banker: premier, uttag och regler`,descriptionEn:`Today’s banks: fees, withdrawals and rules`},{to:`/tradingskolan?course=bankernas-historia&lesson=bank-07-bretton-woods-imf`,labelSv:`Föregående: Bretton Woods och IMF`,labelEn:`Previous: Bretton Woods and the IMF`}]}]";
const mfModules = "[{moduleId:`mf-01-fran-bocker-till-ledger`,moduleTitle:`01 · Från böckerna till ledgern – återblick på skepp och korsfarare`,moduleTitleEn:`01 · From books to the ledger – looking back at ships and crusaders`,summary:`Tempelriddarnas konton, VOC:s aktiebok och bankernas böcker – den röda tråden från pappersbok till delad ledger.`,summaryEn:`The Templars’ accounts, the VOC share register and the banks’ books – the common thread from paper book to shared ledger.`,durationMinutes:14,topics:[`Tempelriddarna`,`VOC`,`Bankböcker`,`Ledger`,`Quiz`],topicsEn:[`Templars`,`VOC`,`Bank books`,`Ledger`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• beskriva hur tempelriddarna och VOC förde böcker över andras pengar och andelar,`,`• förklara vad en ledger är,`,`• följa den röda tråden från pappersböcker till digitala och delade ledgers.`,`# Återblick: skepp och korsfarare`,`I kursen «Marknadens historia» mötte du korsfararna och skeppen. Här tar vi upp tråden igen. Den följer oss genom hela kursen: **ledgern**, boken där någon skriver in vem som äger vad.`,`**Tempelriddarna som bankirer.** Tempelherreorden grundades omkring 1119–1120 för att skydda kristna pilgrimer på väg till Jerusalem. Orden hade hus i många länder i Europa och i det heliga landet. [K1][K2]`,`Tack vare sin styrka kunde orden säkert samla in, förvara och transportera ädelmetall mellan Europa och det heliga landet. Nätverket av förråd och den effektiva transporten gjorde orden attraktiv som bankir åt både kungar och pilgrimer. [K1]`,`Historikern Léopold Delisle gick 1889 igenom de bevarade handlingarna. Ordens hus tog emot insättningar från kungar, furstar, borgare och köpmän. [K2] Parisborgaren Pierre Sarrasin skrev sitt testamente i juni 1220, inför en pilgrimsfärd till Santiago de Compostela. Hans kapital fanns hos Tempelherrarna i Paris, och det som återstod skulle förvaras där tills arvingarna blev myndiga. [K2] Den franske kungens skattkammare låg i Tempelherrarnas hus i Paris i mer än hundra år. [K2]`,`Orden gjorde också betalningar på andra orter genom brev och bokföringsposter, så att pengarna kunde stå kvar där de låg. Flera kunder hade löpande konton hos orden. [K2] År 1235 betalade Henrik III av England in pengar till Tempelherrarnas hus i London, och ordens mästare i England lät betala ut 800 livres tournois vid huset i Paris. [K2]`,`**Skeppen och handelskompanierna.** Det holländska Ostindiska kompaniet, VOC, grundades 1602. [K5] Samma år köpte Pieter Harmensz en andel på 150 gulden i kompaniets kammare i Enkhuizen. Kvittot på hans sista inbetalning 1606 räknas som världens äldsta bevarade aktie. [K3]`,`VOC gav ut kvitton som bevis på betalning. Själva ägandet fanns i kompaniets böcker: bokhållarna förde in varje insats och varje ägarbyte. [K3] Utdelningen betalades ut efter aktieägarregistren i VOC:s sex kammare. [K4]`,`# Från pappersbok till digital bok`,`I kursen «Bankernas historia» följer du hur bankerna tog över boken. När en bank lånar ut skriver den in ett nytt belopp på låntagarens konto, och bankinsättningar är den största delen av pengarna i dag. [K6]`,`Banken för internationella betalningar, BIS, sammanfattar utvecklingen så här: pengar som bokföringsposter hos betrodda mellanhänder gav upphov till nya finansiella instrument, och pappersböckerna ersattes av digitala. [K7]`,`# Vad är en ledger?`,`En ledger är en huvudbok över transaktioner och innehav. En blockkedja är en digital ledger som delas mellan många datorer och som gör ändringar synliga och svåra att genomföra. [K16]`,`# Den röda tråden i kursen`,`• **Lektion 02:** algoritmer och AI lägger order, och företagen för register över sin handel. [K11]`,`• **Lektion 03:** krypto bygger på en ledger som delas mellan deltagarna i ett nätverk. [K14][K16]`,`• **Lektion 04:** en CBDC är centralbankspengar i digital form. Den digitala euron är tänkt att föras på en central plattform som Eurosystemet driver. [K20][K21]`,`• **Lektion 05:** vid en ICO förs nya tokens in i en ledger. [K22]`,`• **Lektion 06:** vid självförvar håller du själv nyckeln till dina poster i ledgern. [K24]`,`• **Lektion 07:** BIS beskriver en framtida «unified ledger» där centralbankspengar, bankpengar och tokeniserade tillgångar samlas. [K8]`,`# Sammanfattning`,`Tempelherrarnas konton, VOC:s aktiebok och bankernas konton är alla betrodda böcker över andras tillgångar. [K2][K3][K6] I dag finns boken också i digital och delad form. [K7][K16]`,`# Källor`,`• [K1] Encyclopaedia Britannica: Templar – https://www.britannica.com/topic/Templars`,`• [K2] Léopold Delisle (1889): Mémoire sur les opérations financières des Templiers. Mémoires de l'Institut national de France, t. 33:2, s. 1–94 (Persée), DOI 10.3406/minf.1889.1515 – https://www.persee.fr/doc/minf_0398-3609_1889_num_33_2_1515`,`• [K3] Westfries Archief: Het oudste aandeel (världens äldsta aktie, VOC Enkhuizen 1602–1606) – https://www.westfriesarchief.nl/verhalen/het-oudste-aandeel/`,`• [K4] Leiden University Libraries, Special Collections Blog (A. Pietersma, 2014-06-19): The world's oldest share certificates – https://www.leidenspecialcollectionsblog.nl/articles/the-worlds-oldest-share-certificates`,`• [K5] Encyclopaedia Britannica: Dutch East India Company (1602–1799) – https://www.britannica.com/topic/Dutch-East-India-Company`,`• [K6] McLeay, Radia & Thomas (2014): Money creation in the modern economy, Bank of England Quarterly Bulletin 2014 Q1 – https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-creation-in-the-modern-economy`,`• [K7] BIS Annual Economic Report 2025, kapitel III: The next-generation monetary and financial system – https://www.bis.org/publ/arpdf/ar2025e3.htm`,`• [K8] BIS Annual Economic Report 2023, kapitel III: Blueprint for the future monetary system: improving the old, enabling the new – https://www.bis.org/publ/arpdf/ar2023e3.htm`,`• [K11] ESMA Interactive Single Rulebook: MiFID II, artikel 17 Algorithmic trading – https://www.esma.europa.eu/publications-and-data/interactive-single-rulebook/mifid-ii/article-17-algorithmic-trading`,`• [K14] Satoshi Nakamoto (2008): Bitcoin: A Peer-to-Peer Electronic Cash System (primärkälla) – https://bitcoin.org/bitcoin.pdf`,`• [K16] NIST IR 8202 (Yaga m.fl., 2018): Blockchain Technology Overview, sammanfattning och avsnitt 3.4.1 – https://nvlpubs.nist.gov/nistpubs/ir/2018/NIST.IR.8202.pdf`,`• [K20] Europeiska centralbanken: Digital euro – FAQs (uppd. 2026-08-17), bl.a. Q14–Q16 och Q20 – https://www.ecb.europa.eu/euro/digital_euro/faqs/html/ecb.faq_digital_euro.en.html`,`• [K21] Sveriges riksbank: E-krona (uppd. 2026-06-29) – https://www.riksbank.se/sv/betalningar--kontanter/e-krona/`,`• [K22] ESMA: ESMA highlights ICO risks for investors and firms (2017-11-13) – https://www.esma.europa.eu/press-news/esma-news/esma-highlights-ico-risks-investors-and-firms`,`• [K24] NIST IR 8301 (Lesavre, Varin & Yaga, 2021): Blockchain Networks: Token Design and Management Overview, avsnitt 3 (hot/cold wallet, s. 11), 3.1 (self-hosted wallets, s. 12) och Key Recovery (s. 14–15) – https://nvlpubs.nist.gov/nistpubs/ir/2021/NIST.IR.8301.pdf`,`⚠️ Endast utbildning. Förenklad historia. Detta är inte råd.`],quiz:[{id:`mf1-q1`,prompt:`Vem anlitade tempelriddarna som bankirer?`,options:[xs(`a`,`Bara köpmän i Amsterdam`,!1),xs(`b`,`Både kungar och pilgrimer`,!0),xs(`c`,`Bara Riksbanken`,!1),xs(`d`,`VOC:s aktieägare`,!1)],explanation:`Ordens nätverk av förråd och säkra transporter gjorde den attraktiv som bankir åt kungar och pilgrimer. [K1]`},{id:`mf1-q2`,prompt:`Hur kunde Tempelherrarna betala ut pengar på en annan ort?`,options:[xs(`a`,`Genom brev och bokföringsposter mellan ordens hus`,!0),xs(`b`,`Genom att trycka sedlar`,!1),xs(`c`,`Via en börs i Amsterdam`,!1),xs(`d`,`Genom en centralbank`,!1)],explanation:`Delisle beskriver betalningar på avstånd genom korrespondens och bokföring, så att pengarna kunde stå kvar. [K2]`},{id:`mf1-q3`,prompt:`Var fanns ägandet i VOC?`,options:[xs(`a`,`I aktiebrev som delades ut`,!1),xs(`b`,`I kompaniets böcker, där varje insats och ägarbyte fördes in`,!0),xs(`c`,`Hos Riksbanken`,!1),xs(`d`,`I en blockkedja`,!1)],explanation:`VOC gav ut kvitton, och bokhållarna förde in insatser och ägarbyten i böckerna. [K3]`},{id:`mf1-q4`,prompt:`Vad är en blockkedja enligt NIST?`,options:[xs(`a`,`En pappersbok i ett bankvalv`,!1),xs(`b`,`En digital ledger som delas mellan många datorer`,!0),xs(`c`,`Ett aktiebrev från VOC`,!1),xs(`d`,`Ett kreditkort`,!1)],explanation:`NIST beskriver blockkedjor som delade digitala ledgers där ändringar syns och är svåra att genomföra. [K16]`}],relatedLinks:[{to:`/tradingskolan?course=historia&lesson=hist-01-skepp-till-aktier`,labelSv:`Marknadens historia: Skepp → aktier`,labelEn:`Market history: Ships → shares`,descriptionSv:`VOC och de första aktierna`,descriptionEn:`The VOC and the first shares`},{to:`/tradingskolan?course=historia&lesson=hist-02-guld-korsfarare`,labelSv:`Marknadens historia: Guld & korsfarare`,labelEn:`Market history: Gold & crusaders`,descriptionSv:`Tidig kredit före bankerna`,descriptionEn:`Early credit before the banks`},{to:`/tradingskolan?course=bankernas-historia`,labelSv:`Kurs: Bankernas historia`,labelEn:`Course: The history of banking`,descriptionSv:`Från Riksbanken 1668 till IMF`,descriptionEn:`From the Riksbank 1668 to the IMF`}]},{moduleId:`mf-02-algoritmer-och-ai`,moduleTitle:`02 · Algoritmisk handel och AI – robotarna på marknaden`,moduleTitleEn:`02 · Algorithmic trading and AI – the robots in the market`,summary:`Vad algoritmisk handel och högfrekvenshandel är enligt MiFID II, vilka krav som gäller och hur ESMA, FSB och BIS ser på AI.`,summaryEn:`What algorithmic and high-frequency trading are under MiFID II, which requirements apply and how ESMA, the FSB and the BIS view AI.`,durationMinutes:14,topics:[`Algoritmisk handel`,`HFT`,`AI`,`MiFID II`,`Quiz`],topicsEn:[`Algorithmic trading`,`HFT`,`AI`,`MiFID II`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad algoritmisk handel och högfrekvenshandel är enligt EU:s regler,`,`• beskriva vilka krav som gäller för företag som handlar algoritmiskt,`,`• beskriva hur AI används i finanssektorn och vad myndigheterna följer.`,`# Vad är algoritmisk handel?`,`Enligt EU:s direktiv MiFID II är algoritmisk handel handel med finansiella instrument där en datoralgoritm automatiskt bestämmer orderns detaljer, till exempel om ordern ska läggas, när, till vilket pris, i vilken mängd och hur den hanteras efteråt. Datorn fattar besluten helt eller till största delen automatiskt. [K10]`,`**Högfrekvenshandel** (HFT) är en form av algoritmisk handel med tre kännetecken: [K10]`,`• infrastruktur som minimerar fördröjningar, till exempel servrar placerade nära handelsplatsen,`,`• systemet bestämmer order helt automatiskt för enskilda affärer,`,`• många meddelanden per dag i form av order, noteringar och makuleringar.`,`# Regler för robotarna`,`Ett värdepappersföretag som handlar algoritmiskt ska enligt MiFID II ha: [K11]`,`• effektiva system och riskkontroller som gör handelssystemen motståndskraftiga och med tillräcklig kapacitet,`,`• tydliga gränser och spärrar för handeln, så att felaktiga order stoppas,`,`• planer för kontinuitet och system som är testade och övervakade.`,`Företaget anmäler den algoritmiska handeln till tillsynsmyndigheten och handelsplatsen och kan behöva beskriva sina strategier, gränser och kontroller. [K11]`,`# Ledgern i handeln`,`Företaget för register som gör att myndigheten kan följa upp att reglerna följs. [K11]`,`Ett företag som använder högfrekvenshandel sparar exakta register i tidsordning över alla order, makuleringar, genomförda affärer och noteringar, och lämnar ut dem till myndigheten på begäran. [K11]`,`Varje robotorder blir alltså en post i en bok, precis som varje ägarbyte i VOC:s aktiebok. [K3][K11]`,`# AI i finanssektorn`,`Finansiella stabilitetsrådet, FSB, beskriver fördelar med AI som effektivare drift, bättre regelefterlevnad, finansiella produkter som anpassas till kunden och avancerad dataanalys. [K13]`,`ESMA nämner kundsupport, upptäckt av bedrägerier, riskhantering, regelefterlevnad och stöd i rådgivning och förvaltning som användningsområden för AI hos värdepappersföretag. [K12]`,`BIS beskriver hur AI-modeller används inom kapitalförvaltning för att bedöma förhållandet mellan risk och avkastning och fördela portföljer. [K9]`,`# Det som myndigheterna följer`,`ESMA förväntar sig att företag som använder AI följer MiFID II, särskilt reglerna om organisation, uppträdande och skyldigheten att agera i kundens bästa intresse. [K12] ESMA lyfter fram fyra områden att bevaka: [K12]`,`• datakvalitet och snedvridning i algoritmerna,`,`• tydlighet i hur beslut fattas,`,`• ett balanserat beroende av AI hos både företag och kunder,`,`• integritet och säkerhet för de stora datamängder som AI behöver.`,`FSB pekar på fyra sårbarheter som kan öka systemrisken: beroende av ett fåtal leverantörer, samvariation på marknaderna, cyberrisker samt modellrisk, datakvalitet och styrning. [K13]`,`BIS beskriver att många aktörer som använder samma algoritmer kan förstärka flockbeteende och svängningar på marknaden. [K9]`,`Fördjupning om automation, risklimiter och övervakning kommer i kursen «AI-handel & riskramar».`,`# Sammanfattning`,`Algoritmer och AI är i dag en del av marknaderna. Reglerna kräver kontroller, gränser och register, och myndigheterna följer utvecklingen noga. Varje order lämnar ett spår i boken. [K10][K11][K12][K13]`,`# Källor`,`• [K3] Westfries Archief: Het oudste aandeel (världens äldsta aktie, VOC Enkhuizen 1602–1606) – https://www.westfriesarchief.nl/verhalen/het-oudste-aandeel/`,`• [K9] BIS Annual Economic Report 2024, kapitel III: Artificial intelligence and the economy: implications for central banks – https://www.bis.org/publ/arpdf/ar2024e3.htm`,`• [K10] ESMA Interactive Single Rulebook: MiFID II (direktiv 2014/65/EU), artikel 4.1 punkt 39–40 – https://www.esma.europa.eu/publications-and-data/interactive-single-rulebook/mifid-ii/article-4-definitions`,`• [K11] ESMA Interactive Single Rulebook: MiFID II, artikel 17 Algorithmic trading – https://www.esma.europa.eu/publications-and-data/interactive-single-rulebook/mifid-ii/article-17-algorithmic-trading`,`• [K12] ESMA: ESMA provides guidance to firms using artificial intelligence in investment services (2024-05-30) – https://www.esma.europa.eu/press-news/esma-news/esma-provides-guidance-firms-using-artificial-intelligence-investment-services`,`• [K13] Financial Stability Board: The Financial Stability Implications of Artificial Intelligence (2024-11-14) – https://www.fsb.org/2024/11/the-financial-stability-implications-of-artificial-intelligence/`,`⚠️ Endast utbildning. Detta är inte råd och inte en rekommendation om någon handelsstrategi eller tjänst.`],quiz:[{id:`mf2-q1`,prompt:`Vad är algoritmisk handel enligt MiFID II?`,options:[xs(`a`,`All handel via internet`,!1),xs(`b`,`Handel där en datoralgoritm automatiskt bestämmer orderns detaljer`,!0),xs(`c`,`Handel med kryptotillgångar`,!1),xs(`d`,`Handel som bara sker på natten`,!1)],explanation:`Definitionen gäller algoritmer som bestämmer om, när, till vilket pris och i vilken mängd en order läggs. [K10]`},{id:`mf2-q2`,prompt:`Vilket register ska ett företag med högfrekvenshandel spara?`,options:[xs(`a`,`Bara de affärer som gav vinst`,!1),xs(`b`,`En lista över kunderna`,!1),xs(`c`,`Exakta register i tidsordning över alla order, makuleringar, affärer och noteringar`,!0),xs(`d`,`Ett register över sina servrar`,!1)],explanation:`Registren lämnas ut till myndigheten på begäran. [K11]`},{id:`mf2-q3`,prompt:`Vad förväntar sig ESMA av företag som använder AI i investeringstjänster?`,options:[xs(`a`,`Att de följer MiFID II, bland annat skyldigheten att agera i kundens bästa intresse`,!0),xs(`b`,`Att de slutar använda algoritmer`,!1),xs(`c`,`Att AI fattar alla beslut`,!1),xs(`d`,`Att kunderna själva kontrollerar AI`,!1)],explanation:`ESMA:s uttalande från 2024 betonar organisation, uppträdande och kundens bästa. [K12]`},{id:`mf2-q4`,prompt:`Vilken sårbarhet lyfter FSB fram?`,options:[xs(`a`,`För få datorer i världen`,!1),xs(`b`,`Beroende av ett fåtal leverantörer av AI-tjänster`,!0),xs(`c`,`Att sedlar försvinner`,!1),xs(`d`,`Att börser stänger på helger`,!1)],explanation:`FSB nämner leverantörskoncentration, samvariation på marknaderna, cyberrisker och modellrisk. [K13]`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-01-fran-bocker-till-ledger`,labelSv:`Föregående: Från böckerna till ledgern`,labelEn:`Previous: From books to the ledger`}]},{moduleId:`mf-03-krypto`,moduleTitle:`03 · Krypto – en ledger som delas`,moduleTitleEn:`03 · Crypto – a ledger that is shared`,summary:`Vad en kryptotillgång är, hur Bitcoin för en gemensam bok, stablecoins och NFT, och EU:s MiCA-förordning.`,summaryEn:`What a crypto-asset is, how Bitcoin keeps a shared book, stablecoins and NFTs, and the EU MiCA Regulation.`,durationMinutes:14,topics:[`Kryptotillgångar`,`Bitcoin`,`Blockkedja`,`Stablecoins`,`MiCA`,`Quiz`],topicsEn:[`Crypto-assets`,`Bitcoin`,`Blockchain`,`Stablecoins`,`MiCA`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad en kryptotillgång är,`,`• beskriva hur Bitcoin använder en delad ledger,`,`• nämna olika typer av kryptotillgångar,`,`• berätta vad EU:s MiCA-förordning innebär.`,`# Vad är en kryptotillgång?`,`Finansinspektionen beskriver en kryptotillgång, ibland kallad kryptovaluta, som en digital representation av ett värde eller en rättighet som kan överföras och lagras elektroniskt med hjälp av blockkedjeteknik. [K17]`,`# Bitcoin och den delade boken`,`I oktober 2008 publicerade en person eller grupp under namnet Satoshi Nakamoto ett förslag till en digital valuta, Bitcoin. Nätverket startade 2009. [K15]`,`Förslaget beskriver elektroniska kontanter som skickas direkt mellan två parter via ett nätverk av datorer. [K14]`,`För att alla ska kunna se att samma mynt används en gång tillkännages transaktionerna offentligt, och deltagarna enas om en gemensam historik över i vilken ordning de kom in. [K14]`,`Nätverket tidsstämplar transaktionerna i en kedja av block. Kedjan blir ett register som kräver att allt arbete görs om för att ändras. [K14]`,`Här tar ledgern ett nytt steg: boken förs gemensamt av deltagarna i nätverket. [K14][K16]`,`# Hur nya bitcoin skapas`,`Nya bitcoin skapas när datorer i nätverket löser ett matematiskt problem, så kallad mining. Ungefär vart fjärde år halveras antalet nya bitcoin per block. Det högsta antalet bitcoin är något under 21 miljoner, och 2025 fanns nästan 20 miljoner. [K15]`,`# Olika typer av kryptotillgångar`,`Enligt Finansinspektionen: [K17]`,`• **Bitcoin** är den mest kända och största kryptotillgången.`,`• **Stablecoins** följer värdet på en eller flera officiella valutor eller andra tillgångar, till exempel guld.`,`• **NFT** (icke-fungibla tokens) kan beskrivas som ett ägarbevis, till exempel för digital konst.`,`ECB skiljer kryptotillgångar från centralbankspengar: centralbanker har i uppdrag att bevara pengarnas värde, medan kryptotillgångar backas och förvaltas utanför centrala institutioner. [K19]`,`# Regler: MiCA`,`MiCA-förordningen (Markets in Crypto-Assets) trädde i kraft i juni 2023. [K18] Under 2024 började den tillämpas. Den ger enhetliga regler för företag som ger ut eller erbjuder tjänster med kryptotillgångar, stärker konsumentskyddet, ökar insynen i produkternas miljöpåverkan och minskar risken att kryptotillgångar används i brottslig verksamhet. [K17]`,`ESMA för ett centralt register över whitepapers för kryptotillgångar, godkända kryptotjänsteleverantörer och aktörer som bryter mot reglerna. [K18]`,`# Så ser myndigheterna på risken`,`EU:s tillsynsmyndigheter ESMA, EBA och EIOPA beskriver de flesta kryptotillgångar som volatila och mycket riskfyllda. Priset kan stiga och falla snabbt. [K27]`,`Finansinspektionen beskriver att risken att förlora pengar när du köper de flesta kryptotillgångar är hög. [K17]`,`# Sammanfattning`,`Kryptotillgångar bygger på en ledger som förs gemensamt i ett nätverk. Bitcoin var först, och i dag finns också stablecoins och NFT. I EU gäller MiCA-förordningen. [K14][K15][K17][K18]`,`# Källor`,`• [K14] Satoshi Nakamoto (2008): Bitcoin: A Peer-to-Peer Electronic Cash System (primärkälla) – https://bitcoin.org/bitcoin.pdf`,`• [K15] Encyclopaedia Britannica (E. Gregersen): Bitcoin (uppd. 2026-09-22) – https://www.britannica.com/money/bitcoin`,`• [K16] NIST IR 8202 (Yaga m.fl., 2018): Blockchain Technology Overview, sammanfattning och avsnitt 3.4.1 – https://nvlpubs.nist.gov/nistpubs/ir/2018/NIST.IR.8202.pdf`,`• [K17] Finansinspektionen: Kryptotillgångar (konsumentsida) – https://www.fi.se/sv/for-konsumenter/kryptotillgangar/`,`• [K18] ESMA: Markets in Crypto-Assets Regulation (MiCA) – https://www.esma.europa.eu/esmas-activities/digital-finance-and-innovation/markets-crypto-assets-regulation-mica`,`• [K19] Europeiska centralbanken: Digital euro – https://www.ecb.europa.eu/euro/digital_euro/html/index.en.html`,`• [K27] ESMA, EBA och EIOPA (2025): Varning för kryptotillgångar (gemensam varning, svensk version, PDF) – https://eba.europa.eu/sites/default/files/2025-10/3454ea12-eda0-4f22-b1f6-f883c61017a5/Updated%20Joint%20ESAs%20revised%20warning%20on%20crypto-assets_SV.pdf`,`⚠️ Endast utbildning. Detta är inte råd och inte en rekommendation att köpa, sälja eller behålla någon kryptotillgång. Kryptotillgångar kan vara mycket riskfyllda. [K27]`],quiz:[{id:`mf3-q1`,prompt:`Hur beskriver Finansinspektionen en kryptotillgång?`,options:[xs(`a`,`En aktie i en bank`,!1),xs(`b`,`En digital representation av ett värde eller en rättighet som överförs och lagras med blockkedjeteknik`,!0),xs(`c`,`En sedel från Riksbanken`,!1),xs(`d`,`Ett sparkonto`,!1)],explanation:`Definitionen finns på FI:s konsumentsida om kryptotillgångar. [K17]`},{id:`mf3-q2`,prompt:`Hur enas deltagarna i Bitcoin om vilka transaktioner som gäller?`,options:[xs(`a`,`En bank bestämmer`,!1),xs(`b`,`Transaktionerna tillkännages offentligt och deltagarna enas om en gemensam historik`,!0),xs(`c`,`Varje användare för en egen bok`,!1),xs(`d`,`Riksbanken godkänner varje transaktion`,!1)],explanation:`Nakamoto beskriver en gemensam historik över i vilken ordning transaktionerna kom in. [K14]`},{id:`mf3-q3`,prompt:`Vad kännetecknar en stablecoin?`,options:[xs(`a`,`Den följer värdet på en eller flera officiella valutor eller andra tillgångar`,!0),xs(`b`,`Den ges ut av en centralbank`,!1),xs(`c`,`Den är en aktie`,!1),xs(`d`,`Den kan bara användas offline`,!1)],explanation:`Finansinspektionen beskriver stablecoins som kryptotillgångar som följer en valuta eller en annan tillgång. [K17]`},{id:`mf3-q4`,prompt:`Vad gör MiCA-förordningen?`,options:[xs(`a`,`Den inför euron i Sverige`,!1),xs(`b`,`Den gäller bara aktier`,!1),xs(`c`,`Den ger enhetliga regler i EU för företag som ger ut eller erbjuder tjänster med kryptotillgångar`,!0),xs(`d`,`Den bestämmer priset på bitcoin`,!1)],explanation:`MiCA stärker bland annat konsumentskyddet och insynen. [K17]`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-02-algoritmer-och-ai`,labelSv:`Föregående: Algoritmer och AI`,labelEn:`Previous: Algorithms and AI`}]},{moduleId:`mf-04-cbdc`,moduleTitle:`04 · CBDC – e-kronan och den digitala euron`,moduleTitleEn:`04 · CBDC – the e-krona and the digital euro`,summary:`Var arbetet med e-kronan står, hur den digitala euron är tänkt att fungera och när den kan komma, och en jämförelse med krypto och bankpengar.`,summaryEn:`Where work on the e-krona stands, how the digital euro is meant to work and when it may arrive, and a comparison with crypto and bank money.`,durationMinutes:14,topics:[`CBDC`,`E-krona`,`Digital euro`,`Centralbankspengar`,`Quiz`],topicsEn:[`CBDC`,`E-krona`,`Digital euro`,`Central bank money`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad en CBDC (digitala centralbankspengar) är,`,`• berätta var arbetet med e-kronan står,`,`• beskriva hur den digitala euron är tänkt att fungera och när den kan komma,`,`• jämföra krypto, CBDC och bankpengar.`,`# Vad är en CBDC?`,`CBDC står för central bank digital currency, digitala centralbankspengar. [K21]`,`I Sverige har allmänheten i dag tillgång till kronor i två former: kontanter från staten och digitala pengar från privata aktörer, främst inlåning i banker. [K21]`,`# E-kronan`,`E-kronor skulle vara svenska, digitala kronor utgivna av Riksbanken. De skulle komplettera kontanterna. [K21]`,`Enligt Riksbanken kan e-kronor stärka motståndskraften på betalningsmarknaden, fungera offline, öka konkurrensen och bidra till finansiell inkludering. [K21]`,`Riksbanken startade e-kronaprojektet 2017. Från 2020 testade e-kronapiloten en möjlig teknisk plattform. Projektet och piloten avslutades 2023. [K21]`,`Att införa e-kronor är ett politiskt beslut. I Betalningsrapport 2026 föreslog Riksbanken att en utredning om nödvändiga lagändringar tillsätts, så att en e-krona kan införas inom rimlig tid om riksdagen beslutar det. [K21]`,`# Den digitala euron`,`Den digitala euron skulle vara en digital form av kontanter, utgiven av centralbanken och tillgänglig för alla i euroområdet. Den skulle komplettera sedlar och mynt. [K19]`,`Enligt ECB: [K20]`,`• Den digitala euron skulle vara lagligt betalningsmedel, och en digital euro är alltid värd en euro.`,`• Den skulle kunna användas både online och offline. Vid betalningar offline känner bara betalaren och mottagaren till transaktionsuppgifterna.`,`• Personuppgifterna skyddas: Eurosystemet skulle hålla isär transaktionerna och enskilda personers identitet.`,`• Den skulle kunna användas fritt: var, när och med vem bestämmer användaren. Villkorade betalningar, till exempel betalning vid leverans, skulle vara möjliga.`,`• Innehavet är räntefritt, precis som kontanter i plånboken.`,`# Ledgern i en CBDC`,`Den digitala euron är tänkt att gå på en central avvecklingsplattform där Eurosystemet hanterar och verifierar alla transaktioner och innehav. Plattformen bygger på vedertagna standarder och använder viktiga designprinciper från tekniken för distribuerade ledgers. [K20]`,`Här förs boken alltså av centralbanken, medan kryptots bok förs gemensamt i ett nätverk. [K14][K20]`,`# Var står den digitala euron?`,`Förberedelsefasen pågick från november 2023 till oktober 2025. [K20] I oktober 2025 beslutade ECB-rådet att projektet går vidare till nästa fas. [K19]`,`En pilot med en betaversion planeras starta under andra halvåret 2027 och pågå i tolv månader. [K20]`,`ECB siktar på att vara redo för en möjlig första utgivning under 2029, förutsatt att EU-förordningen om den digitala euron antas före slutet av 2026. [K20]`,`# Krypto, CBDC och bankpengar`,`• Vem ger ut? – Krypto: Ett nätverk av deltagare, till exempel Bitcoin [K14] · CBDC: Centralbanken [K20][K21] · Bankpengar: Affärsbanken, när den lånar ut [K6]`,`• Vem för boken? – Krypto: Deltagarna i nätverket [K14] · CBDC: Centralbanken, i den digitala euron via en central plattform [K20] · Bankpengar: Banken [K6]`,`• Värde – Krypto: Kan svänga kraftigt [K27] · CBDC: En digital euro är alltid värd en euro [K20] · Bankpengar: Kronor på kontot kan växlas mot centralbankspengar, så en krona är lika mycket värd i alla banker [K21]`,`# Sammanfattning`,`En CBDC är centralbankspengar i digital form. Riksbanken följer arbetet med den digitala euron noga, och ECB siktar på att vara redo 2029. [K19][K20][K21]`,`# Källor`,`• [K6] McLeay, Radia & Thomas (2014): Money creation in the modern economy, Bank of England Quarterly Bulletin 2014 Q1 – https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-creation-in-the-modern-economy`,`• [K14] Satoshi Nakamoto (2008): Bitcoin: A Peer-to-Peer Electronic Cash System (primärkälla) – https://bitcoin.org/bitcoin.pdf`,`• [K19] Europeiska centralbanken: Digital euro – https://www.ecb.europa.eu/euro/digital_euro/html/index.en.html`,`• [K20] Europeiska centralbanken: Digital euro – FAQs (uppd. 2026-08-17), bl.a. Q14–Q16 och Q20 – https://www.ecb.europa.eu/euro/digital_euro/faqs/html/ecb.faq_digital_euro.en.html`,`• [K21] Sveriges riksbank: E-krona (uppd. 2026-06-29) – https://www.riksbank.se/sv/betalningar--kontanter/e-krona/`,`• [K27] ESMA, EBA och EIOPA (2025): Varning för kryptotillgångar (gemensam varning, svensk version, PDF) – https://eba.europa.eu/sites/default/files/2025-10/3454ea12-eda0-4f22-b1f6-f883c61017a5/Updated%20Joint%20ESAs%20revised%20warning%20on%20crypto-assets_SV.pdf`,`⚠️ Endast utbildning. Planerna kan ändras. Detta är inte råd.`],quiz:[{id:`mf4-q1`,prompt:`Vem skulle ge ut e-kronor?`,options:[xs(`a`,`Affärsbankerna`,!1),xs(`b`,`Riksbanken`,!0),xs(`c`,`ECB`,!1),xs(`d`,`Ett kryptonätverk`,!1)],explanation:`E-kronor skulle vara digitala kronor utgivna av Riksbanken. [K21]`},{id:`mf4-q2`,prompt:`Vem beslutar om Sverige ska införa e-kronor?`,options:[xs(`a`,`Bankerna`,!1),xs(`b`,`ECB`,!1),xs(`c`,`Politikerna, genom riksdagen`,!0),xs(`d`,`Finansinspektionen`,!1)],explanation:`Riksbanken beskriver införandet som ett politiskt beslut. [K21]`},{id:`mf4-q3`,prompt:`När siktar ECB på att vara redo för en första utgivning av den digitala euron?`,options:[xs(`a`,`2025`,!1),xs(`b`,`2027`,!1),xs(`c`,`2029, om EU-förordningen antas före slutet av 2026`,!0),xs(`d`,`2040`,!1)],explanation:`Piloten planeras till andra halvåret 2027, och målet för en möjlig utgivning är 2029. [K20]`},{id:`mf4-q4`,prompt:`Vilket påstående om den digitala euron stämmer enligt ECB?`,options:[xs(`a`,`Den betalar hög ränta`,!1),xs(`b`,`Den kan användas offline, och en digital euro är alltid värd en euro`,!0),xs(`c`,`Den är en kryptotillgång`,!1),xs(`d`,`Den ersätter sedlarna`,!1)],explanation:`Den digitala euron skulle fungera online och offline och komplettera kontanterna. [K19][K20]`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-03-krypto`,labelSv:`Föregående: Krypto`,labelEn:`Previous: Crypto`}]},{moduleId:`mf-05-ico-och-tokens`,moduleTitle:`05 · ICO och tokens – nya andelar i boken`,moduleTitleEn:`05 · ICOs and tokens – new shares in the book`,summary:`Vad en ICO är, olika slags tokens och whitepapers enligt MiCA. Fördjupning finns i kursen ICO & tokenerbjudanden.`,summaryEn:`What an ICO is, different kinds of tokens and white papers under MiCA. More in the course ICO & token offerings.`,durationMinutes:10,topics:[`ICO`,`Tokens`,`Whitepaper`,`MiCA`,`Quiz`],topicsEn:[`ICO`,`Tokens`,`White paper`,`MiCA`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad en ICO är,`,`• beskriva olika slags tokens,`,`• berätta var du hittar whitepapers enligt MiCA.`,`# Vad är en ICO?`,`En ICO (initial coin offering) är ett sätt att ta in pengar från allmänheten med hjälp av så kallade coins eller tokens. Den kallas också token sale. Ett företag eller en person ger ut tokens och säljer dem mot vanliga valutor som euro eller, oftare, mot kryptotillgångar som bitcoin eller ether. [K22]`,`ICO:er används för att finansiera olika projekt, bland annat företag som bygger på blockkedjor eller distribuerade ledgers. [K22]`,`# Olika slags tokens`,`Enligt ESMA varierar tokens mellan olika ICO:er: [K22]`,`• en del ger tillgång till en tjänst eller produkt som utgivaren utvecklar,`,`• en del ger rösträtt eller en andel av framtida intäkter,`,`• en del handlas på särskilda handelsplatser efter utgivningen.`,`Jämför med VOC 1602: andelen fördes in i kompaniets bok. [K3] Vid en ICO förs de nya tokens in i en digital ledger. [K22]`,`# Whitepapers enligt MiCA`,`Enligt MiCA lämnas informationen om en kryptotillgång i ett whitepaper. ESMA publicerar ett centralt register över whitepapers för kryptotillgångar. [K18]`,`Utgivaren eller den som erbjuder kryptotillgången ansvarar ensam för innehållet i whitepapret. Registret är en förteckning, och whitepapren publiceras på utgivarens eget ansvar. [K18]`,`Sedan den 23 december 2025 ska whitepapers vara maskinläsbara i formatet iXBRL. [K18]`,`# Myndigheternas syn`,`ESMA varnade redan 2017 för att ICO:er är mycket riskfyllda och spekulativa och att priset på tokens ofta svänger kraftigt. [K22]`,`Whitepaper, tokenomics, reglering, bedrägerimönster och skillnaden mot en börsintroduktion går vi igenom i kursen «ICO & tokenerbjudanden».`,`# Sammanfattning`,`En ICO skapar nya tokens i en digital ledger, ungefär som VOC förde in nya andelar i sin bok. Under MiCA finns informationen i ett whitepaper som utgivaren ansvarar för. [K3][K18][K22]`,`# Källor`,`• [K3] Westfries Archief: Het oudste aandeel (världens äldsta aktie, VOC Enkhuizen 1602–1606) – https://www.westfriesarchief.nl/verhalen/het-oudste-aandeel/`,`• [K18] ESMA: Markets in Crypto-Assets Regulation (MiCA) – https://www.esma.europa.eu/esmas-activities/digital-finance-and-innovation/markets-crypto-assets-regulation-mica`,`• [K22] ESMA: ESMA highlights ICO risks for investors and firms (2017-11-13) – https://www.esma.europa.eu/press-news/esma-news/esma-highlights-ico-risks-investors-and-firms`,`⚠️ Endast utbildning. Detta är inte råd och inte en rekommendation om något tokenerbjudande. ICO:er kan vara mycket riskfyllda. [K22]`],quiz:[{id:`mf5-q1`,prompt:`Vad är en ICO enligt ESMA?`,options:[xs(`a`,`En börsintroduktion av en bank`,!1),xs(`b`,`Ett sätt att ta in pengar från allmänheten med coins eller tokens`,!0),xs(`c`,`En centralbanksvaluta`,!1),xs(`d`,`En försäkring`,!1)],explanation:`ICO kallas också token sale. [K22]`},{id:`mf5-q2`,prompt:`Vem ansvarar för innehållet i ett whitepaper enligt MiCA?`,options:[xs(`a`,`ESMA`,!1),xs(`b`,`Riksbanken`,!1),xs(`c`,`Utgivaren eller den som erbjuder kryptotillgången`,!0),xs(`d`,`Köparen`,!1)],explanation:`Whitepapers i ESMA:s register är utgivarens ansvar. [K18]`},{id:`mf5-q3`,prompt:`Vilken koppling finns mellan en ICO och VOC:s aktiebok?`,options:[xs(`a`,`Båda för in nya andelar i en bok, VOC i en pappersbok och en ICO i en digital ledger`,!0),xs(`b`,`Båda gavs ut av Riksbanken`,!1),xs(`c`,`Båda handlades bara offline`,!1),xs(`d`,`Båda saknade ägare`,!1)],explanation:`VOC förde in insatserna i sina böcker, och en ICO skapar tokens i en ledger. [K3][K22]`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-04-cbdc`,labelSv:`Föregående: CBDC`,labelEn:`Previous: CBDC`}]},{moduleId:`mf-06-sjalvforvar-kall-planbok`,moduleTitle:`06 · Självförvar och kall plånbok`,moduleTitleEn:`06 · Self-custody and cold wallets`,summary:`Självförvar, varm och kall plånbok, varför offline-nycklar minskar attackytan och hur du gör en säker backup av återställningsfrasen.`,summaryEn:`Self-custody, hot and cold wallets, why offline keys reduce the attack surface and how to back up a recovery phrase safely.`,durationMinutes:14,topics:[`Självförvar`,`Plånbok`,`Kall förvaring`,`Återställningsfras`,`Quiz`],topicsEn:[`Self-custody`,`Wallet`,`Cold storage`,`Recovery phrase`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• förklara vad självförvar innebär,`,`• beskriva skillnaden mellan varm och kall plånbok,`,`• förklara varför nycklar som förvaras offline minskar attackytan,`,`• göra en säker backup av en återställningsfras.`,`# Nyckeln till din post i boken`,`Tempelherrarna och VOC förde böckerna åt sina kunder, och i dag för bankerna boken. [K2][K3][K6] I en delad ledger för användarna in sina transaktioner själva, och de hanterar och lagrar själva sina privata nycklar, ofta i en plånbok. [K16]`,`# Nycklar och plånböcker`,`En privat nyckel är en hemlig kod som bevisar att du äger något i blockkedjan. [K23]`,`En plånbok är ett program som skapar, hanterar, lagrar eller använder privata och publika nycklar. Den kan vara mjukvara eller en särskild hårdvaruenhet. [K24]`,`# Självförvar`,`Du kan förvara nycklarna själv eller låta en förvarare sköta dem åt dig. [K24]`,`Vid självförvar sköter du allt lokalt: du skapar nycklarna, förvarar dem säkert, gör backup, kan återställa dem och granskar och signerar varje transaktion. Du väljer själv säkerhetsnivån, och ditt godkännande krävs före varje transaktion. [K24]`,`Självförvar innebär också fullt ansvar för nycklarna. Därför är en genomtänkt backup och noggrann granskning av varje transaktion en del av vardagen. [K24]`,`# Varm och kall plånbok`,`NIST delar in plånböcker efter om de är uppkopplade mot internet. [K24]`,`• Anslutning – Varm plånbok: Uppkopplad mot internet · Kall plånbok: Offline, frånkopplad från internet`,`• Används för – Varm plånbok: Snabb åtkomst, mindre belopp och pengar i rörelse · Kall plånbok: Hög säkerhet, större belopp som ligger still`,`• Signering – Varm plånbok: Direkt i den uppkopplade enheten · Kall plånbok: Kräver ett fysiskt steg, till exempel en knapptryckning, en lokal PIN-kod eller en QR-kod`,`• Exempel på form – Varm plånbok: Program i telefonen eller datorn · Kall plånbok: Särskild hårdvaruplånbok eller en dator som hålls helt isolerad från nätverk`,`Källa för tabellen: [K24]`,`De två typerna används ofta för olika ändamål: den varma för pengar i rörelse och den kalla för det som ligger still. NIST beskriver också ett mellanled som kan lägga in tidsfördröjning, beloppsgränser eller flera signaturer före uttag. [K24]`,`# Varför offline-nycklar minskar attackytan`,`Attackytan är alla punkter där en angripare kan försöka ta sig in i ett system, påverka det eller hämta data ur det. [K26]`,`En hårdvaruplånbok förvarar de privata nycklarna offline. Nyckeln stannar hela tiden lokalt på enheten. [K25]`,`Att hålla privata nycklarna offline minskar risken för intrång kraftigt, även om en angripare skulle ta kontroll över din dator. [K25]`,`En kall plånbok kräver dessutom ett fysiskt steg för att signera, till exempel en knapptryckning på enheten. [K24]`,`Nyckeln finns alltså på färre ställen som går att nå via internet. Attackytan blir mindre. [K25][K26]`,`Privata nycklar ska skyddas mot obehörigt röjande. Det gäller all kryptografi, också i banker och myndigheter. [K28]`,`# Backup av återställningsfrasen`,`Återställningsfrasen (seed phrase) är en lista med ord som du får när plånboken skapas. Med den kan du ta dig tillbaka in i plånboken. [K23] Med en och samma fras kan alla konton i plånboken återställas på en gång. [K24]`,`Frasen är huvudnyckeln till plånboken: den som har frasen kommer åt alla konton. [K25]`,`Så gör du en säker backup:`,`1. **Skriv ned frasen** och förvara kopian på en säker plats som bara du har tillgång till. En papperskopia är en vanlig form av backup. [K24]`,`2. **Skydda backupen mot förlust, stöld och skador.** Det gäller både papperskopior och digitala kopior. [K24]`,`3. **Håll frasen offline.** Skriv den för hand i stället för att ta en skärmdump. Skärmdumpar kan synkas till molnet, och nycklar hämtade från molnet är en vanlig attackväg. [K25]`,`4. **Behåll frasen för dig själv.** Frasen och de privata nycklarna stannar hos dig. Seriösa tjänster, supportpersonal och webbplatser sköter sitt arbete med andra uppgifter. [K25]`,`5. **Dubbelkolla mottagaradressen** innan du skickar en transaktion. [K25]`,`6. **Håll enheter och program uppdaterade**, använd starka och unika lösenord och logga in via säkra nätverk. [K27]`,`# Sammanfattning`,`Vid självförvar är det du som håller nyckeln till din post i ledgern. En kall plånbok håller nyckeln offline, och en väl förvarad återställningsfras gör att du alltid kan komma tillbaka in. [K24][K25]`,`# Källor`,`• [K2] Léopold Delisle (1889): Mémoire sur les opérations financières des Templiers. Mémoires de l'Institut national de France, t. 33:2, s. 1–94 (Persée), DOI 10.3406/minf.1889.1515 – https://www.persee.fr/doc/minf_0398-3609_1889_num_33_2_1515`,`• [K3] Westfries Archief: Het oudste aandeel (världens äldsta aktie, VOC Enkhuizen 1602–1606) – https://www.westfriesarchief.nl/verhalen/het-oudste-aandeel/`,`• [K6] McLeay, Radia & Thomas (2014): Money creation in the modern economy, Bank of England Quarterly Bulletin 2014 Q1 – https://www.bankofengland.co.uk/quarterly-bulletin/2014/q1/money-creation-in-the-modern-economy`,`• [K16] NIST IR 8202 (Yaga m.fl., 2018): Blockchain Technology Overview, sammanfattning och avsnitt 3.4.1 – https://nvlpubs.nist.gov/nistpubs/ir/2018/NIST.IR.8202.pdf`,`• [K23] Ethereum.org: Ethereum glossary (private key, seed phrase) – https://ethereum.org/glossary/`,`• [K24] NIST IR 8301 (Lesavre, Varin & Yaga, 2021): Blockchain Networks: Token Design and Management Overview, avsnitt 3 (hot/cold wallet, s. 11), 3.1 (self-hosted wallets, s. 12) och Key Recovery (s. 14–15) – https://nvlpubs.nist.gov/nistpubs/ir/2021/NIST.IR.8301.pdf`,`• [K25] Ethereum.org: Ethereum security and scam prevention (uppd. 2026-06-06), avsnittet Wallet security – https://ethereum.org/en/security/`,`• [K26] NIST CSRC Glossary: attack surface (efter NIST SP 800-53 Rev. 5) – https://csrc.nist.gov/glossary/term/attack_surface`,`• [K27] ESMA, EBA och EIOPA (2025): Varning för kryptotillgångar (gemensam varning, svensk version, PDF) – https://eba.europa.eu/sites/default/files/2025-10/3454ea12-eda0-4f22-b1f6-f883c61017a5/Updated%20Joint%20ESAs%20revised%20warning%20on%20crypto-assets_SV.pdf`,`• [K28] NIST SP 800-57 Part 1 Rev. 5 (2020): Recommendation for Key Management – https://csrc.nist.gov/pubs/sp/800/57/pt1/r5/final`,`⚠️ Endast utbildning. Lektionen nämner inga produkter och är inte råd eller en rekommendation om kryptotillgångar eller förvaringslösningar. Kryptotillgångar kan vara mycket riskfyllda. [K27]`],quiz:[{id:`mf6-q1`,prompt:`Vad innebär självförvar?`,options:[xs(`a`,`Du skapar, förvarar och säkerhetskopierar dina nycklar själv och godkänner varje transaktion`,!0),xs(`b`,`Banken förvarar allt åt dig`,!1),xs(`c`,`Nycklarna ligger hos en börs`,!1),xs(`d`,`Du delar nycklarna med supporten`,!1)],explanation:`Vid självförvar ligger nyckelhantering, backup och signering hos användaren. [K24]`},{id:`mf6-q2`,prompt:`Vad kännetecknar en kall plånbok?`,options:[xs(`a`,`Den är alltid uppkopplad`,!1),xs(`b`,`Den används bara för små belopp`,!1),xs(`c`,`Nycklarna förvaras offline och signering kräver ett fysiskt steg`,!0),xs(`d`,`Den sköts av en bank`,!1)],explanation:`En kall plånbok är frånkopplad från internet och kräver till exempel en knapptryckning eller en lokal PIN-kod för att signera. [K24]`},{id:`mf6-q3`,prompt:`Varför minskar offline-nycklar attackytan?`,options:[xs(`a`,`Nyckeln finns på färre ställen som går att nå via internet, även om datorn angrips`,!0),xs(`b`,`De gör transaktioner snabbare`,!1),xs(`c`,`De ersätter återställningsfrasen`,!1),xs(`d`,`De höjer värdet på tillgångarna`,!1)],explanation:`Att hålla privata nycklar offline minskar risken för intrång kraftigt, även om en angripare tar kontroll över datorn. [K25][K26]`},{id:`mf6-q4`,prompt:`Hur gör du en säker backup av återställningsfrasen?`,options:[xs(`a`,`Tar en skärmdump som sparas i molnet`,!1),xs(`b`,`Skriver ned den och förvarar kopian säkert, för dig själv`,!0),xs(`c`,`Mejlar den till supporten`,!1),xs(`d`,`Delar den i en chatt`,!1)],explanation:`Frasen är huvudnyckeln till plånboken. Skriv ned den, håll den offline och behåll den för dig själv. [K24][K25]`}],relatedLinks:[{to:`/tradingskolan?course=historia&lesson=hist-05-bokforing-verktyg`,labelSv:`Marknadens historia: Bokföring och spår`,labelEn:`Market history: Bookkeeping and trails`,descriptionSv:`Handelsböcker och dubbel bokföring`,descriptionEn:`Ledgers and double-entry bookkeeping`},{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-05-ico-och-tokens`,labelSv:`Föregående: ICO och tokens`,labelEn:`Previous: ICOs and tokens`}]},{moduleId:`mf-07-framtiden-enligt-kallorna`,moduleTitle:`07 · Framtiden enligt källorna`,moduleTitleEn:`07 · The future according to the sources`,summary:`BIS unified ledger och tokenisering, ECB:s och Riksbankens planer, ESMA:s tillsyn av AI och tokenisering – och ledgerns tidslinje.`,summaryEn:`The BIS unified ledger and tokenisation, ECB and Riksbank plans, ESMA supervision of AI and tokenisation – and the ledger timeline.`,durationMinutes:12,topics:[`Tokenisering`,`Unified ledger`,`CBDC`,`AI-tillsyn`,`Tidslinje`,`Quiz`],topicsEn:[`Tokenisation`,`Unified ledger`,`CBDC`,`AI supervision`,`Timeline`,`Quiz`],content:[`# Lärandemål`,`Efter lektionen kan du`,`• återge hur BIS beskriver framtidens penning- och finanssystem,`,`• nämna de planer som ECB, Riksbanken och ESMA själva har publicerat,`,`• följa ledgerns tidslinje från 1100-talet till i dag.`,`Alla framtidsbilder i lektionen är källornas egna. Kursen återger dem.`,`# BIS: en «unified ledger»`,`BIS presenterade 2023 en ritning för det framtida penningsystemet. Tokenisering av pengar och tillgångar har enligt BIS stor potential. En ny typ av finansiell infrastruktur, en «unified ledger», skulle kunna samla centralbankspengar, tokeniserade bankinsättningar och tokeniserade tillgångar på en programmerbar plattform. [K8]`,`Flera ledgers med olika användningsområden skulle kunna finnas samtidigt och kopplas ihop, enligt BIS. [K8]`,`# BIS 2025: nästa generations system`,`BIS beskriver tokenisering som en innovation som både förbättrar det gamla och möjliggör det nya, till exempel inom betalningar mellan länder och värdepappersmarknader. [K7]`,`Enligt BIS kan tokeniserade plattformar med centralbanksreserver, bankpengar och statsobligationer i centrum lägga grunden för nästa generations penning- och finanssystem. [K7]`,`BIS prövar stablecoins mot tre krav för ett penningsystem: att alla pengar är lika mycket värda (singleness), att penningmängden kan anpassas efter behovet (elasticity) och att systemet skyddas mot brott (integrity). BIS bedömer att stablecoins uppfyller dessa krav i otillräcklig grad för att bära penningsystemet. [K7]`,`# Centralbankernas och myndigheternas planer`,`• **ECB:** en pilot med den digitala euron under andra halvåret 2027 och beredskap för en möjlig första utgivning 2029, om EU-förordningen antas före slutet av 2026. [K20]`,`• **Riksbanken:** följer arbetet med den digitala euron och har föreslagit en utredning om de lagändringar som behövs för en e-krona. [K21]`,`• **ESMA:** inför från 2027 en ny prioritering i tillsynen för digital innovation, med fokus först på hur företagen använder AI och tokenisering. [K29]`,`• **FSB:** rekommenderar att myndigheter förbättrar övervakningen av AI, prövar om regelverken räcker till och stärker sin egen förmåga, bland annat med AI-verktyg. [K13]`,`• **BIS:** uppmanar centralbanker att samarbeta i en gemenskap där de delar kunskap, data och AI-verktyg. [K9]`,`# Ledgerns tidslinje`,`• 1119–1120 – Tempelherreorden grundas [K1]`,`• 1235 – Tempelherrarna betalar ut i Paris mot en inbetalning i London [K2]`,`• 1602 – VOC grundas, aktieägarna förs in i kompaniets böcker [K3][K5]`,`• 2008 – Satoshi Nakamoto publicerar förslaget till Bitcoin [K15]`,`• 2009 – Bitcoinnätverket startar [K15]`,`• 2017 – Riksbanken startar e-kronaprojektet [K21]`,`• 2023 – MiCA träder i kraft och BIS presenterar idén om en unified ledger [K18][K8]`,`• 2025 – ECB:s förberedelsefas för den digitala euron avslutas [K20]`,`• 2027 – Planerad pilot med den digitala euron och ESMA:s nya tillsynsprioritering [K20][K29]`,`• 2029 – ECB:s mål för en möjlig första utgivning av den digitala euron [K20]`,`# Sammanfattning`,`Från tempelherrarnas konton till en möjlig unified ledger handlar det om samma sak: en betrodd bok över vem som äger vad. Källorna beskriver en framtid med tokenisering, digitala centralbankspengar och AI under tillsyn. [K2][K7][K8][K20]`,`# Källor`,`• [K1] Encyclopaedia Britannica: Templar – https://www.britannica.com/topic/Templars`,`• [K2] Léopold Delisle (1889): Mémoire sur les opérations financières des Templiers. Mémoires de l'Institut national de France, t. 33:2, s. 1–94 (Persée), DOI 10.3406/minf.1889.1515 – https://www.persee.fr/doc/minf_0398-3609_1889_num_33_2_1515`,`• [K3] Westfries Archief: Het oudste aandeel (världens äldsta aktie, VOC Enkhuizen 1602–1606) – https://www.westfriesarchief.nl/verhalen/het-oudste-aandeel/`,`• [K5] Encyclopaedia Britannica: Dutch East India Company (1602–1799) – https://www.britannica.com/topic/Dutch-East-India-Company`,`• [K7] BIS Annual Economic Report 2025, kapitel III: The next-generation monetary and financial system – https://www.bis.org/publ/arpdf/ar2025e3.htm`,`• [K8] BIS Annual Economic Report 2023, kapitel III: Blueprint for the future monetary system: improving the old, enabling the new – https://www.bis.org/publ/arpdf/ar2023e3.htm`,`• [K9] BIS Annual Economic Report 2024, kapitel III: Artificial intelligence and the economy: implications for central banks – https://www.bis.org/publ/arpdf/ar2024e3.htm`,`• [K13] Financial Stability Board: The Financial Stability Implications of Artificial Intelligence (2024-11-14) – https://www.fsb.org/2024/11/the-financial-stability-implications-of-artificial-intelligence/`,`• [K15] Encyclopaedia Britannica (E. Gregersen): Bitcoin (uppd. 2026-09-22) – https://www.britannica.com/money/bitcoin`,`• [K16] NIST IR 8202 (Yaga m.fl., 2018): Blockchain Technology Overview, sammanfattning och avsnitt 3.4.1 – https://nvlpubs.nist.gov/nistpubs/ir/2018/NIST.IR.8202.pdf`,`• [K18] ESMA: Markets in Crypto-Assets Regulation (MiCA) – https://www.esma.europa.eu/esmas-activities/digital-finance-and-innovation/markets-crypto-assets-regulation-mica`,`• [K20] Europeiska centralbanken: Digital euro – FAQs (uppd. 2026-08-17), bl.a. Q14–Q16 och Q20 – https://www.ecb.europa.eu/euro/digital_euro/faqs/html/ecb.faq_digital_euro.en.html`,`• [K21] Sveriges riksbank: E-krona (uppd. 2026-06-29) – https://www.riksbank.se/sv/betalningar--kontanter/e-krona/`,`• [K29] ESMA: ESMA sets new supervisory priority on digital innovation from 2027 (2026-09-23) – https://www.esma.europa.eu/press-news/esma-news/esma-sets-new-supervisory-priority-digital-innovation-2027`,`⚠️ Endast utbildning. Framtidsbilderna är källornas egna och kan ändras. Detta är inte råd.`],quiz:[{id:`mf7-q1`,prompt:`Vad är en «unified ledger» enligt BIS?`,options:[xs(`a`,`En ny kryptovaluta`,!1),xs(`b`,`En plattform som samlar centralbankspengar, tokeniserade bankinsättningar och tokeniserade tillgångar`,!0),xs(`c`,`En bokföringsbok i en bank`,!1),xs(`d`,`En aktiebok från VOC`,!1)],explanation:`BIS beskrev idén 2023 som en ny typ av finansiell infrastruktur. [K8]`},{id:`mf7-q2`,prompt:`Vilka tre krav prövar BIS stablecoins mot?`,options:[xs(`a`,`Pris, volym och hastighet`,!1),xs(`b`,`Singleness, elasticity och integrity`,!0),xs(`c`,`Ränta, skatt och avgift`,!1),xs(`d`,`Guld, silver och koppar`,!1)],explanation:`BIS bedömer att stablecoins uppfyller kraven i otillräcklig grad för att bära penningsystemet. [K7]`},{id:`mf7-q3`,prompt:`Vad fokuserar ESMA:s nya tillsynsprioritering från 2027 på först?`,options:[xs(`a`,`Sedlar och mynt`,!1),xs(`b`,`Hur företagen använder AI och tokenisering`,!0),xs(`c`,`Fastighetspriser`,!1),xs(`d`,`Guldreserver`,!1)],explanation:`ESMA vill att tillsynen har kunskap och kapacitet för nya tekniker. [K29]`},{id:`mf7-q4`,prompt:`Vad är den röda tråden i kursen?`,options:[xs(`a`,`Ledgern, en betrodd bok över vem som äger vad`,!0),xs(`b`,`Guld som enda säkra tillgång`,!1),xs(`c`,`Att robotar ersätter människor`,!1),xs(`d`,`Att allt blir kontantlöst`,!1)],explanation:`Tråden går från tempelherrarnas konton och VOC:s bok till delade och digitala ledgers. [K2][K3][K16]`}],relatedLinks:[{to:`/tradingskolan?course=marknadens-framtid&lesson=mf-06-sjalvforvar-kall-planbok`,labelSv:`Föregående: Självförvar`,labelEn:`Previous: Self-custody`}]}]";
const bankCourse = "{courseId:`bankernas-historia`,order:1.5,status:`available`,titleKey:`school.course.bankHistoria.title`,summaryKey:`school.course.bankHistoria.summary`,titleSv:`Bankernas historia`,titleEn:`The history of banking`,summarySv:`Riksbanken 1668, Bank of England 1694, familjen Rothschild och 1800-talets banker, delreservsystemet, Federal Reserve 1913 och IMF från Bretton Woods 1944 – och hur det hänger ihop i dag.`,summaryEn:`The Riksbank 1668, the Bank of England 1694, the Rothschild family and 19th-century banking, fractional reserve banking, the Federal Reserve 1913 and the IMF from Bretton Woods 1944 – and how it connects today.`,topicsSv:[`Centralbanker`,`Rothschild`,`Delreserv`,`Fed`,`IMF`,`Quiz`],topicsEn:[`Central banks`,`Rothschild`,`Fractional reserve`,`Fed`,`IMF`,`Quiz`],modules:bankMods,plannedLessons:8,coverImage:`/school/courses/bankernas-historia.jpg`}";
const mfCourse = "{courseId:`marknadens-framtid`,order:1.6,status:`available`,titleKey:`school.course.marknadensFramtid.title`,summaryKey:`school.course.marknadensFramtid.summary`,titleSv:`Marknadens framtid – Robotåldern`,titleEn:`The future of markets – The robot age`,summarySv:`Från tempelriddarnas och VOC:s böcker till den delade ledgern: algoritmer och AI, krypto, e-kronan och den digitala euron, ICO, självförvar och framtiden enligt källorna.`,summaryEn:`From the books of the Templars and the VOC to the shared ledger: algorithms and AI, crypto, the e-krona and the digital euro, ICOs, self-custody and the future according to the sources.`,topicsSv:[`Ledger`,`Algoritmer`,`AI`,`Krypto`,`CBDC`,`ICO`,`Självförvar`,`Quiz`],topicsEn:[`Ledger`,`Algorithms`,`AI`,`Crypto`,`CBDC`,`ICO`,`Self-custody`,`Quiz`],modules:mfMods,plannedLessons:7,coverImage:`/school/courses/marknadens-framtid.jpg`}";

const MOD_ANCHOR = ",Ms=[{courseId:`basics-sprak`";
const CAT_ANCHOR = "modules:Es,plannedLessons:5,coverImage:`/school/courses/historia.jpg`},{courseId:`ico`";
const ALIAS_FROM = 'guld:`historia`,"europa-syd":`europa-syd`';
const ALIAS_TO = 'guld:`historia`,"bankernas-historia":`bankernas-historia`,bankhistoria:`bankernas-historia`,"bank-history":`bankernas-historia`,"marknadens-framtid":`marknadens-framtid`,robotaldern:`marknadens-framtid`,"future-markets":`marknadens-framtid`,"europa-syd":`europa-syd`';

function count(hay, needle) {
  return hay.split(needle).length - 1;
}

function once(label, from, to) {
  const n = count(s, from);
  if (n !== 1) throw new Error(`${label}: expected 1 occurrence, found ${n}`);
  s = s.replace(from, to);
  console.log("ok", label);
}

const already =
  s.includes("courseId:`bankernas-historia`") &&
  s.includes("courseId:`marknadens-framtid`") &&
  s.includes(",bankMods=") &&
  s.includes(",mfMods=") &&
  s.includes(ALIAS_TO);

if (already) {
  console.log("skip courses");
} else {
  if (
    s.includes("courseId:`bankernas-historia`") ||
    s.includes("courseId:`marknadens-framtid`") ||
    s.includes(",bankMods=") ||
    s.includes(",mfMods=") ||
    s.includes('"bankernas-historia":`bankernas-historia`')
  ) {
    throw new Error("partial course patch");
  }
  once("modules", MOD_ANCHOR, `,bankMods=${bankModules},mfMods=${mfModules}${MOD_ANCHOR}`);
  once(
    "catalog",
    CAT_ANCHOR,
    `modules:Es,plannedLessons:5,coverImage:\`/school/courses/historia.jpg\`},${bankCourse},${mfCourse},{courseId:\`ico\``,
  );
  once("alias", ALIAS_FROM, ALIAS_TO);
}

const bankIds = [
  "bank-01-riksbanken-1668",
  "bank-02-bank-of-england-1694",
  "bank-03-rothschild-1800-talet",
  "bank-04-rothschild-efter-1800-talet",
  "bank-05-delreservsystemet",
  "bank-06-federal-reserve-1913",
  "bank-07-bretton-woods-imf",
  "bank-08-sa-hanger-det-ihop",
];
const mfIds = [
  "mf-01-fran-bocker-till-ledger",
  "mf-02-algoritmer-och-ai",
  "mf-03-krypto",
  "mf-04-cbdc",
  "mf-05-ico-och-tokens",
  "mf-06-sjalvforvar-kall-planbok",
  "mf-07-framtiden-enligt-kallorna",
];

const checks = [
  ["bank course once", count(s, "courseId:`bankernas-historia`") === 1],
  ["future course once", count(s, "courseId:`marknadens-framtid`") === 1],
  ["bank modules spliced", s.includes(`,bankMods=${bankModules},`)],
  ["future modules spliced", s.includes(`,mfMods=${mfModules},`)],
  ["bank cover", s.includes("coverImage:`/school/courses/bankernas-historia.jpg`")],
  ["future cover", s.includes("coverImage:`/school/courses/marknadens-framtid.jpg`")],
  ["alias", s.includes(ALIAS_TO) && count(s, ALIAS_TO) === 1],
  ["historia still before banks", s.indexOf("courseId:`historia`") < s.indexOf("courseId:`bankernas-historia`")],
  ["banks before future", s.indexOf("courseId:`bankernas-historia`") < s.indexOf("courseId:`marknadens-framtid`")],
  ["future before ico", s.indexOf("courseId:`marknadens-framtid`") < s.indexOf("courseId:`ico`")],
  ...bankIds.map((id) => [`module ${id}`, count(s, `moduleId:\`${id}\``) === 1]),
  ...mfIds.map((id) => [`module ${id}`, count(s, `moduleId:\`${id}\``) === 1]),
  ["basics clip still gone", s.includes("var In={};") && !s.includes("basics-01-samma-sprak.mp4")],
  ["compound sv clip", s.includes("youtubeUrlSv:`https://www.youtube.com/watch?v=MvNGY5UzdF4`")],
  ["leverage sv clip", s.includes("youtubeUrlSv:`https://www.youtube.com/watch?v=oUAhA_BXsNE`")],
  ["ted-ed kept", s.includes("https://www.youtube.com/watch?v=p7HKvqRI_Bo")],
  ["om-modellen kept", s.includes("/om-modellen")],
  ["nvda-rider kept", s.includes("/nvda-rider/")],
  ["archived balans kept", s.includes("archived-record/balans")],
  ["archived shein kept", s.includes("archived-record/shein")],
  ["light theme hook kept", s.includes("data-theme")],
];

const failed = checks.filter(([, ok]) => !ok);
if (failed.length) throw new Error(`post-checks failed: ${failed.map(([name]) => name).join(", ")}`);

fs.writeFileSync(bundlePath, s);
console.log("patched", bundlePath.pathname, "bytes", s.length);
